-- --------------------------------------------------------

--
-- Estrutura para tabela `planocontas`
--

DROP TABLE IF EXISTS `planocontas`;
CREATE TABLE `planocontas` (
  `id` bigint(20) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `codconta` varchar(11) NOT NULL DEFAULT '0',
  `descricao` varchar(40) NOT NULL,
  `obs` longtext DEFAULT 'Null'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Despejando dados para a tabela `planocontas`
--

INSERT INTO `planocontas` (`id`, `created_at`, `updated_at`, `codconta`, `descricao`, `obs`) VALUES
(1, NULL, NULL, '1.1.0', 'Ativo', '\'O ativo é um dos componentes fundamentais do Balanço Patrimonial, representando onde os recursos da empresa foram investidos.'),
(2, NULL, NULL, '1.1.1', 'Ativo Circulante', '\'Bens e direitos que podem ser convertidos em dinheiro ou consumidos em um período de até um ano.’'),
(3, NULL, NULL, '1.1.2', 'Disponível', '\'Refere-se aos recursos financeiros de alta liquidez que uma empresa ou pessoa física possui e que podem ser utilizados imediatamente para pagamentos ou outras necessidades\''),
(4, NULL, NULL, '1.1.3', 'Caixa', '\'a conta Caixa representa o dinheiro em espécie que uma empresa possui em suas instalações (cofre, gaveta, etc.) e que está disponível para uso imediato\''),
(5, NULL, NULL, '1.1.4', 'Bancos Conta Movimento', '\'refere-se à conta contábil do Ativo Circulante que registra o saldo disponível nas contas correntes bancárias de uma empresa. \'\'refere-se à conta contábil do Ativo Circulante que registra o saldo disponível nas contas correntes bancárias de uma empresa.\''),
(6, NULL, NULL, '1.1.5', 'Aplicações Financeiras de Curto Prazo', '\'representam investimentos realizados por uma empresa ou indivíduo com o objetivo de obter rendimentos em um período relativamente curto, geralmente inferior a um ano\''),
(7, NULL, NULL, '1.2.0', 'Contas a Receber', '\'valores que uma empresa tem o direito de receber de seus clientes pela venda de mercadorias ou pela prestação de serviços a crédito.\''),
(8, NULL, NULL, '1.2.1', 'Clientes', '\'Contas a Receber. Refere-se aos valores que uma empresa tem o direito de receber de seus clientes pela venda de mercadorias ou pela prestação de serviços a crédito.\''),
(9, NULL, NULL, '1.2.2', 'Duplicatas a Receber', '\'Duplicatas a Receber é uma conta específica dentro do Ativo Circulante que representa um tipo de Contas a Receber\''),
(10, NULL, NULL, '1.2.3', 'Adiantamentos a Fornecedores', '\'pagando antecipadamente por bens ou serviços que ainda serão entregues ou prestados no futuro. \''),
(11, NULL, NULL, '1.3.0', 'Estoques', '\'conjunto de bens tangíveis que uma empresa mantém\''),
(12, NULL, NULL, '1.3.1', 'Mercadorias para Revenda', '\'Mercadorias para Revenda são um tipo específico de Estoques mantido por empresas comerciais.\''),
(13, NULL, NULL, '1.3.2', 'Matéria-Prima', '\'A Matéria-Prima é um tipo de Estoque específico de empresas industriais.\''),
(14, NULL, NULL, '1.3.3', 'Produtos em Elaboração', '\'Produtos em Elaboração (ou Produtos em Processo) são um tipo de Estoques específico de empresas industriais. Eles representam os bens que se encontram em fase de produção, ou seja, já passaram por alguma etapa do processo produtivo\''),
(15, NULL, NULL, '1.4.0', 'Outros Ativos Circulantes', '\'Ativo Circulante que engloba bens e direitos que a empresa espera realizar (converter em dinheiro, vender ou consumir) dentro do seu ciclo operacional normal ou em até doze meses após a data do balanço, mas que não se encaixam nas contas específicas já mencionadas, como Caixa, Bancos, Aplicações Financeiras de Curto Prazo, Contas a Receber, Adiantamentos a Fornecedores e Estoques.\''),
(16, NULL, NULL, '1.4.1', 'Impostos a Recuperar', '\'Ativo Circulante que representa os valores de tributos pagos a mais, indevidamente ou que geraram créditos a serem utilizados pela empresa para compensar débitos futuros com o mesmo ou outros impostos.\''),
(17, NULL, NULL, '1.4.2', 'Despesas Antecipadas', '\'Ativo no Balanço Patrimonial de uma empresa. Mais especificamente, elas fazem parte do Ativo Circulante.\''),
(18, NULL, NULL, '2.1.0', 'Ativo Não Circulante', '\'Bens e direitos que não se destinam à venda ou à conversão em dinheiro a curto prazo, sendo utilizados na operação da empresa por um período superior a um ano.\''),
(19, NULL, NULL, '2.1.1', 'Ativo Imobilizado', '\'Bens tangíveis (físicos) utilizados na operação da empresa, como terrenos, edifícios, máquinas, equipamentos, veículos, móveis e utensílios.\''),
(20, NULL, NULL, '2.1.2', 'Terrenos', '\'Bens tangíveis (físicos) utilizados na operação da empresa\''),
(21, NULL, NULL, '2.1.3', 'Edificações', '\'Bens tangíveis (físicos) utilizados na operação da empresa\''),
(22, NULL, NULL, '2.1.4', 'Máquinas e Equipamentos', '\'Bens tangíveis (físicos) utilizados na operação da empresa\''),
(23, NULL, NULL, '2.1.5', 'Veículos', '\'Bens tangíveis (físicos) utilizados na operação da empresa\''),
(24, NULL, NULL, '2.1.6', 'Móveis e Utensílios', '\'Bens tangíveis (físicos) utilizados na operação da empresa\''),
(25, NULL, NULL, '2.1.7', '(-) Depreciação Acumulada', '\'Bens não físicos que possuem valor econômico para a empresa, como marcas, patentes, softwares, direitos autorais, goodwill.\''),
(26, NULL, NULL, '2.2.0', 'Ativo Intangível', 'um ativo intangível é um bem não físico que possui valor econômico para uma empresa.'),
(27, NULL, NULL, '2.2.1', 'Marcas e Patentes', 'marcas e patentes são classificadas como ativos intangíveis'),
(28, NULL, NULL, '2.2.2', 'Softwares', 'ativo intangível por ser um bem não físico, identificável e controlado pela empresa, com expectativa de gerar benefícios econômicos futuros.'),
(29, NULL, NULL, '2.2.3', '(-) Amortização Acumulada', 'é uma conta contábil redutora do Ativo Intangível que representa o montante total da amortização já reconhecida ao longo da vida útil de um ativo intangível específico.'),
(30, NULL, NULL, '2.3.0', 'Investimentos', 'Descrição da Conta'),
(31, NULL, NULL, '2.3.1', 'Participações em Outras Empresas', 'Descrição da Conta'),
(32, NULL, NULL, '2.3.2', 'Realizável à Longo Prazo', '\'Direitos que a empresa tem a receber após o período de um ano.\''),
(33, NULL, NULL, '3.1.0', 'Passivo', '\'O passivo é um dos componentes fundamentais do Balanço Patrimonial, representando a origem dos recursos de terceiros utilizados para financiar o ativo (bens e direitos) da entidade.\''),
(34, NULL, NULL, '3.1.1', 'Passivo Circulante', '\'Obrigações com vencimento em até um ano. Exemplos: contas a pagar a fornecedores, salários a pagar, impostos a recolher, empréstimos de curto prazo.\''),
(35, NULL, NULL, '3.1.2', 'Obrigações com Fornecedores', '\'Obrigações financeiras da empresa com terceiros, até Um Ano\''),
(36, NULL, NULL, '3.1.3', 'Fornecedores Nacionais', '\'Obrigações financeiras da empresa com terceiros, até Um Ano\''),
(37, NULL, NULL, '3.1.4', 'Fornecedores Internacionais', '\'Obrigações financeiras da empresa com terceiros, até Um Ano\''),
(38, NULL, NULL, '3.2.0', 'Obrigações Trabalhistas', 'Obrigações Trabalhistas referem-se ao conjunto de deveres e responsabilidades que um empregador tem para com seus empregados, conforme a legislação trabalhista vigente (principalmente a Consolidação das Leis do Trabalho - CLT) e outras normas específicas.'),
(39, NULL, NULL, '3.2.1', 'Salários a Pagar', 'é uma conta do Passivo Circulante que representa a obrigação da empresa de pagar aos seus funcionários os salários referentes aos dias já trabalhados, mas que ainda não foram pagos até a data do balanço patrimonial.'),
(40, NULL, NULL, '3.2.2', 'Encargos Sociais a Pagar', 'conta do Passivo Circulante que representa a obrigação da empresa de recolher e pagar aos órgãos competentes os valores referentes aos encargos sociais incidentes sobre a folha de pagamento dos seus funcionários, relativos a um determinado período (geralmente o mês trabalhado), mas que ainda não foram pagos até a data do balanço patrimonial.'),
(41, NULL, NULL, '3.2.3', 'Férias a Pagar', 'é uma conta do Passivo Circulante que representa a obrigação da empresa de pagar aos seus funcionários os valores referentes às férias que já foram adquiridas (período aquisitivo completo) ou proporcionais (em caso de rescisão ou férias coletivas), mas que ainda não foram pagas até a data do balanço patrimonial.'),
(42, NULL, NULL, '3.3.0', 'Obrigações Tributárias', 'Obrigações Tributárias referem-se ao conjunto de deveres que pessoas físicas e jurídicas têm perante o fisco (governo federal, estadual ou municipal) relacionados à apuração e ao pagamento de tributos.;'),
(43, NULL, NULL, '3.3.1', 'Impostos a Pagar (ICMS, IPI, ISS)', 'Impostos, Taxas, Tarifas'),
(44, NULL, NULL, '3.3.2', 'Contribuições a Pagar (INSS, FGTS)', 'Impostos, Taxas, Tarifas'),
(45, NULL, NULL, '3.4.0', 'Empréstimos e Financiamentos de Curto Pr', 'representam obrigações financeiras que uma empresa ou indivíduo contrai com instituições financeiras ou outras entidades, com vencimento em um período de até um ano a partir da data do balanço patrimonial.'),
(46, NULL, NULL, '3.5.0', 'Outras Obrigações', 'é uma conta do Passivo Circulante no Balanço Patrimonial que agrupa obrigações da empresa que não se encaixam nas categorias mais específicas.'),
(47, NULL, NULL, '3.6.0', 'Dividendos a Pagar', 'é uma conta do Passivo Circulante no Balanço Patrimonial que representa a obrigação da empresa de distribuir aos seus acionistas uma parcela dos lucros que foi declarada, mas ainda não foi efetivamente paga até a data do balanço.'),
(48, NULL, NULL, '3.7.0', 'Adiantamentos de Clientes', 'é uma conta do Passivo Circulante no Balanço Patrimonial que representa os valores recebidos de clientes por bens ou serviços que ainda não foram totalmente entregues ou prestados até a data do balanço.'),
(49, NULL, NULL, '4.1.1', 'Empréstimos e Financiamentos de Longo Pr', '\'Descrição da Conta\''),
(50, NULL, NULL, '4.1.2', 'Outras Obrigações de Longo Prazo', 'Obrigações Tributárias referem-se ao conjunto de deveres que pessoas físicas e jurídicas'),
(51, NULL, NULL, '5.1.0', 'Patrimônio Líquido', 'O Patrimônio Líquido (PL) representa o valor residual dos ativos de uma entidade após a dedução de todos os seus passivos. Em outras palavras, é a riqueza líquida da empresa, o valor que pertence aos seus proprietários ou acionistas.'),
(52, NULL, NULL, '5.1.1', 'Capital Social', '\'É o patrimônio inicial da empresa, registrado no Contrato Social ou Estatuto Social, e serve como base financeira para as operações iniciais e como garantia para terceiros.\''),
(53, NULL, NULL, '5.1.2', 'Capital Social Subscrito', '\'Capital Social Subscrito refere-se ao valor total dos recursos que os sócios ou acionistas se comprometem a investir na empresa, conforme estabelecido no Contrato Social ou Estatuto Social no momento da sua constituição ou em aumentos de capital.\''),
(54, NULL, NULL, '5.1.3', 'Capital Social Integralizado', '\'O Capital Social Integralizado representa a parcela do Capital Social Subscrito que os sócios ou acionistas efetivamente pagaram ou transferiram para o patrimônio da empresa, seja em dinheiro, bens ou direitos.\''),
(55, NULL, NULL, '5.2.0', 'Reservas', 'refere-se a uma parcela específica do Patrimônio Líquido de uma empresa, destinada a finalidades específicas. As reservas representam lucros retidos ou outras fontes de recursos que não estão disponíveis para distribuição imediata aos proprietários (sócios ou acionistas).'),
(56, NULL, NULL, '5.2.1', 'Reserva Legal', 'é uma conta do Patrimônio Líquido de uma sociedade anônima (S.A.) ou de uma sociedade limitada (Ltda.), constituída com uma parcela do lucro líquido de cada exercício social. É uma reserva obrigatória, conforme previsto na Lei nº 6.404/76 (Lei das S.A.) e no Código Civil.'),
(57, NULL, NULL, '5.2.2', 'Reserva de Lucros', '\'Reservas de Lucros são contas do Patrimônio Líquido de uma empresa que representam a parcela do lucro líquido de cada exercício social que foi retida e não distribuída aos sócios ou acionistas.\''),
(58, NULL, NULL, '5.3.0', 'Lucros ou Prejuízos Acumulados', '\'Lucros ou Prejuízos Acumulados é uma conta do Patrimônio Líquido (PL) de uma empresa que representa o resultado líquido (lucro ou prejuízo) gerado pela empresa em períodos anteriores e que ainda não foi distribuído aos sócios/acionistas, transferido para reservas de lucros ou utilizado para compensar prejuízos.\''),
(59, NULL, NULL, '6.1.0', 'Receitas', '\'receitas, no contexto da contabilidade, refere-se ao fluxo de entrada de recursos econômicos para uma entidade (empresa, organização, pessoa física ou jurídica) resultante de suas atividades normais e que provoca um aumento no patrimônio líquido.\''),
(60, NULL, NULL, '6.1.1', 'Receita Bruta de Vendas', '\'Receita Bruta de Vendas representa o valor total das vendas de bens ou serviços que constituem a atividade principal de uma empresa, antes de quaisquer deduções ou descontos.\''),
(61, NULL, NULL, '6.1.2', 'Venda de Mercadorias', '\'Alienação de bens adquiridos de terceiros com o objetivo de revenda, visando lucro.\''),
(62, NULL, NULL, '6.1.3', 'Prestação de Serviços', '\'A Prestação de Serviços é a atividade econômica que envolve a realização de um trabalho ou fornecimento de uma utilidade para terceiros, mediante remuneração, sem a transferência da propriedade de um bem tangível.\''),
(63, NULL, NULL, '6.2.0', 'Deduções da Receita Bruta', '\'Deduções da Receita Bruta são os valores que são subtraídos da Receita Bruta de Vendas para se chegar à Receita Líquida de Vendas. Essas deduções representam itens que, embora tenham entrado inicialmente no faturamento total da empresa, não representam a receita líquida efetiva que a empresa dispõe.\''),
(64, NULL, NULL, '6.2.1', 'Impostos sobre Vendas (ICMS, PIS, COFINS', '\'Os Impostos sobre Vendas são tributos que incidem diretamente sobre o valor da comercialização de bens e serviços.\''),
(65, NULL, NULL, '6.2.2', 'Devoluções de Vendas', '\'As Devoluções de Vendas representam o valor das mercadorias que foram vendidas pela empresa, mas que, por algum motivo (defeito, insatisfação do cliente, erro no pedido, etc.), retornam ao seu estoque. Essa operação implica o cancelamento parcial ou total da venda original.\''),
(66, NULL, NULL, '6.2.3', 'Descontos Concedidos', '\'Os Descontos Concedidos representam as reduções no preço de venda de mercadorias ou serviços que uma empresa oferece aos seus clientes.\''),
(67, NULL, NULL, '6.3.0', 'Receitas Financeiras', '\'são os lucros que a empresa obtém através da gestão de seus recursos financeiros, em vez da venda de seus produtos ou da prestação de seus serviços.\''),
(68, NULL, NULL, '6.3.1', 'Juros Ativos', '\'Juros Ativos representam os rendimentos que uma empresa ou indivíduo recebe em decorrência de ter emprestado dinheiro ou aplicado capital em investimentos. Em outras palavras, são os juros a favor da entidade que os recebe.\''),
(69, NULL, NULL, '6.3.2', 'Descontos Obtidos', '\'Os Descontos Obtidos representam as reduções no preço de compra de bens ou serviços que uma empresa consegue de seus fornecedores. Esses descontos podem ser concedidos por diversos motivos, como pagamento antecipado, compra em grande volume, promoções especiais ou por relacionamento comercial.'),
(70, NULL, NULL, '7.1.0', 'Custos', '\'A palavra custos, no contexto da contabilidade, refere-se aos gastos e sacrifícios econômicos que uma empresa realiza para produzir bens ou serviços. Em outras palavras, são os valores dos recursos consumidos ou utilizados no processo de produção ou na prestação de serviços.\''),
(71, NULL, NULL, '7.1.1', 'Custo das Mercadorias Vendidas (CMV)', '\'O Custo das Mercadorias Vendidas (CMV) é uma conta de resultado que representa o custo dos produtos que foram efetivamente vendidos por uma empresa em um determinado período. Ele é essencial para calcular o Lucro Bruto, que é a diferença entre a Receita Líquida de Vendas e o CMV.\''),
(72, NULL, NULL, '7.2.0', 'Custo dos Serviços Prestados (CSP)', '\'Cconta de resultado que representa o conjunto de gastos diretamente relacionados à prestação dos serviços que uma empresa oferece em um determinado período.\''),
(73, NULL, NULL, '7.3.0', 'Custos com Pessoal', '\'Os Custos com Pessoal representam a totalidade dos gastos que uma empresa ou organização tem com seus funcionários e colaboradores. Esses custos são essenciais para o funcionamento de qualquer entidade que dependa de força de trabalho e abrangem uma variedade de itens além do salário base.\''),
(74, NULL, NULL, '7.4.0', 'Custos Gerais de Produção', '\'Os Custos Gerais de Produção (CGP), também conhecidos como Custos Indiretos de Fabricação (CIF) ou Gastos Gerais de Fabricação (GGF), englobam todos os custos de produção que não podem ser diretamente atribuídos a um produto específico. \''),
(75, NULL, NULL, '8.1.0', 'Despesas', '\'despesas representam os gastos e sacrifícios econômicos que uma empresa realiza para obter receita e manter suas operações funcionando.\''),
(76, NULL, NULL, '8.1.1', 'Despesas com Vendas', '\'Despesas com Vendas são os gastos e sacrifícios econômicos que uma empresa realiza especificamente para promover, divulgar e comercializar seus produtos ou serviços, com o objetivo final de gerar receita. \''),
(77, NULL, NULL, '8.1.2', 'Salários e Comissões', '\'Salários e Comissões são duas formas de remuneração de empregados, mas possuem características distintas e são tratadas de maneiras específicas na contabilidade e na folha de pagamento.\''),
(78, NULL, NULL, '8.1.2', 'Propaganda e Publicidade', '\'Propaganda e Publicidade são duas ferramentas de comunicação de marketing que as empresas utilizam para promover seus produtos, serviços, ideias ou marcas, com o objetivo de influenciar o comportamento do público-alvo.\''),
(79, NULL, NULL, '8.2.0', 'Despesas Administrativas', '\'Despesas Administrativas são os gastos e sacrifícios econômicos que uma empresa realiza para gerenciar e operar o negócio como um todo, mas que não estão diretamente ligados à produção de bens ou à prestação de serviços.\''),
(80, NULL, NULL, '8.2.1', 'Salários e Ordenados', '\'Salários e Ordenados representam a remuneração bruta paga aos empregados e administradores de uma empresa em contraprestação pelos serviços prestados durante um determinado período.\''),
(81, NULL, NULL, '8.2.2', 'Aluguéis', '\'Aluguéis representam os pagamentos periódicos que uma empresa ou indivíduo realiza pelo direito de usar um ativo que pertence a outra parte.\''),
(82, NULL, NULL, '8.2.3', 'Materiais de Escritório', '\'Materiais de Escritório representam os diversos itens consumíveis e de uso geral necessários para o funcionamento das atividades administrativas e de suporte de uma empresa ou organização. \''),
(83, NULL, NULL, '8.3.0', 'Despesas Financeiras', '\'Despesas Financeiras representam os gastos e sacrifícios econômicos que uma empresa realiza em decorrência de suas operações de natureza financeira, que não estão diretamente ligadas à sua atividade principal (operacional).\''),
(84, NULL, NULL, '8.3.1', 'Juros Passivos', '\'Juros Passivos representam os encargos financeiros que uma empresa ou indivíduo paga pelo uso de capital de terceiros. Em outras palavras, são os custos decorrentes de empréstimos, financiamentos, debêntures, arrendamentos financeiros (leasing) e outras formas de dívida.\''),
(85, NULL, NULL, '8.3.2', 'Despesas Bancárias', '\'Despesas Bancárias são os valores cobrados pelas instituições financeiras (bancos, cooperativas de crédito, etc.) pela prestação de diversos serviços ou pela manutenção de produtos financeiros utilizados pela empresa.\''),
(86, NULL, NULL, '8.4.0', 'Outras Despesas Operacionais', '\'Demonstração do Resultado do Exercício (DRE) que engloba gastos e sacrifícios econômicos que são relacionados à atividade operacional da empresa, mas que não se enquadram nas categorias específicas de Despesas Administrativas ou Despesas com Vendas.\'');

