INSERT INTO `textos` (`id`, `nome`, `area_id`, `texto_id`, `status`, `created_at`, `updated_at`, `obs`, `texto`, `avatar`, `nmtexto`) VALUES
(1, 'PROCURAÇÃO AD JUDICIA ET EXTRA', 10, 0, 'A', '2024-05-23 16:28:01', '2026-04-29 01:20:24', 'A procuração ad judicia esta no campo Direito Processual Civil e é um instrumento jurídico essencial no Direito Brasileiro,permitindo a representação legal de uma pessoa física ou jurídica por meio de um advogado.Essa procuração concede poderes gerais para atuação do advogado, permitindo que ele pratique atos de foro geral e também extrajudiciais para defesa e representação diante de tribunais e demais agentes do direito. o advogado fica habilitado a conduzir todos os atos do processo do outorgante, com exceção daqueles delimitados no Art. 105 do Novo Código de Processo Civil.', '<p>OUTORGANTE: Nome Outorgante, NACIONALIDADE, ESTADO CIVIL, SITUA&Ccedil;&Atilde;O OCUPACIONAL, RG No. 00.000.000-4, CPF No. 000.000.000-00 domiciliado e residente &agrave; ENDERE&Ccedil;O, 00 BAIRRO CEP 01234-999, ESTADO / UF OUTORGADO: NOME ADVOGADO, NACIONALIDADE, ESTADO CIVIL SITUA&Ccedil;&Atilde;O OCUPACIONAL CPF No. 000.000.000-00, Inscrito na Ordem dos Advogados do Brasil sob No. 123456 / UF, com escrit&oacute;rio profissional sito &agrave; ENDERE&Ccedil;O, 00 BAIRRO CEP 01234-999, ESTADO / UF Atrav&eacute;s do presente instrumento particular de mandato, o OUTORGANTE nomeia e constitui como seu procurador o OUTORGADO, concedendo-lhe amplos poderes inerentes ao bom e fiel cumprimento deste mandato, bem como foro em geral, conforme estabelecido no artigo 38 do C&oacute;digo de Processo Civil, e os especiais para transigir, fazer acordo, firmar compromisso, substabelecer, reconhecer a proced&ecirc;ncia do pedido, reconhecer intima&ccedil;&otilde;es, receber e dar quita&ccedil;&atilde;o, praticar todos os atos perante a parti&ccedil;&otilde;es p&uacute;blicas Federai, Estaduais e Municipais e Org&atilde;os da administra&ccedil;&atilde;o p&uacute;blica direta e indireta, praticar quaisquer atos perante particulares ou empresas privadas, recorrer a quaisquer inst&acirc;ncias e tribunais, podendo atuar em conjunto ou separadamente, dando tudo por bom e valioso.</p>', 'adjudicia.png', NULL),
(2, 'HABEAS CORPUS - FALTA DE JUSTA CAUSA', 2, 0, 'A', '2024-05-23 16:28:01', '2025-08-26 21:15:52', 'No âmbito jurídico, o habeas corpus é um dos instrumentos mais importantes para a proteção da liberdade individual, É um remédio constitucional que visa garantir o direito fundamental de locomoção (o direito de ir e vir) de uma pessoa que esteja sofrendo ou esteja sob ameaça de sofrer uma violência ou coação ilegal em sua liberdade, seja por ilegalidade ou por abuso de poder. ', 'Excelentíssimo(a) Senhor(a) Doutor(a) Juiz(a) de Direito da ___ Vara Criminal da Comarca de ____________ – ___ Processo nº ________ Acusado: (nome)Advogado: (nome), OAB/___ nº ___ (art. 396-A, CPP) NOME DO ACUSADO, já qualificado nos autos em epígrafe, por intermédio de seu advogado que esta subscreve, vem, respeitosamente, à presença de Vossa Excelência, apresentar sua DEFESA PRÉVIA, com fundamento no art. 396-A do Código de Processo Penal, pelos fatos e fundamentos a seguir expostos: O Ministério Público ofereceu denúncia imputando ao acusado a prática do crime previsto no art. ___ do Código Penal, sob o argumento de que, em (data), teria supostamente _______________________. Inépcia da denúncia – (caso aplicável: ausência de justa causa, denúncia genérica, falta de individualização da conduta etc.). Nulidades processuais – (eventual vício na citação, ausência de laudo pericial, cerceamento de defesa etc.). Negativa de autoria – O acusado não praticou o fato descrito, conforme demonstram (indicar provas/testemunhas). Atipicidade da conduta – A conduta narrada não configura crime, por ausência de dolo/culpa ou pela insignificância penal. Excludentes de ilicitude – Caso concreto: legítima defesa, estado de necessidade, estrito cumprimento do dever legal etc. Excludentes de culpabilidade – Caso aplicável: inimputabilidade, coação moral irresistível, erro de proibição inevitável. Nos termos do art. 396-A, CPP, requer-se: A oitiva das testemunhas abaixo arroladas: Nome, profissão, endereço completo Nome, profissão, endereço completo(...) A produção de todos os meios de prova em direito admitidos, em especial documental, pericial e testemunhal. Diante do exposto, requer a Vossa Excelência: O recebimento da presente Defesa Prévia; O reconhecimento das preliminares arguídas e, se acolhidas, a absolvição sumária do acusado (art. 397 do CPP); Caso superadas, seja deferida a produção de provas requeridas; Ao final, a absolvição do acusado, nos termos do art. 386, incisos do CPP.', 'texto.png', NULL),
(3, 'REPETIÇÃO DE INDÉBITO - ICMS-TUSD/TUST', 4, 0, 'A', '2024-05-23 16:28:01', '2025-07-01 23:46:30', 'A repetição de indébito é repetição de indébito de ICMS sobre TUST e TUSD é da Justiça Estadual, direito e a ação que tem como objetivo a devolução de valores cobrados indevidamente e deve ser impetrada na Fazenda Pública Estaduala. Taxa de Utilização de Serviços de Distribuição e  TUST representa a Tarifa de Utilização de Serviços de Transmissão. Nas tarifas estão relacionadas à compra de energia elétrica.', 'Pessoa jurídica de direito privado, com sede na Rua .... nº ...., na cidade de ...., inscrita no CGC/MF sob o n° ...., por seu procurador infra assinado (procuração em anexo), vem, com o devido respeito, fundamentada no art. 165, inciso I, do Código Tributário Nacional e nos artigos 282 e seguintes do Código de Processo Civil, propor, como de fato propõe, AÇÃO ORDINÁRIA DE REPETIÇÃO DE INDÉBITO contra o INSTITUTO NACIONAL DE SEGURIDADE SOCIAL - INSS, (qualificação), fazendo-o pelas razões de fato e de direito a seguir articuladamente deduzidas: OS FATOS 01. A Requerente, dando cumprimento aos seus objetivos sociais, mantém atividades regulares desde o início de sua constituição, sendo dirigida por uma Administração composta de diretores e com designação específica segundo as funções desempenhadas. Como tantas e outras empresas, se utiliza, também, de serviços prestados por \"Autônomos\", na maioria profissionais liberais, com registros próprios e com inscrição regular junto aos órgãos de fiscalização, inclusive e também junto ao Instituto Nacional de Seguridade Social, o ora Requerido. 02. Em razão do disposto no art. 3º da Lei 7.789/89, o Requerido passou a exigir de todas as empresas (logo também da Requerente), o recolhimento da contribuição e na alíquota de 20% (vinte por cento), \"sobre o total das remunerações pagas ou creditadas, a qualquer título, no decorrer do mês, aos segurados empregados, avulsos, autônomos que mantiveram relacionamento com a Requerente-Autora e \"a qualquer título\". 03. A respeito da contribuição exigida sobre o pagamento feito aos Sócios-Gerentes, a título de \"pro-labore\", a Requerente-Autora, inclusive e por entender devida a exigência, impetrou Mandado de Segurança perante o Juízo da .... Vara da Justiça Federal, Seção Judiciária deste Estado, autos de n° ...., processo que já foi julgado pelo Egrégio Tribunal Regional Federal e com a \"baixa\" à instância de origem, onde recebeu ordem de arquivamento, após a conversão em \"receita\" dos valores depositados no referido processo. 04. Entrementes, o SUPREMO TRIBUNAL FEDERAL, em MAIO de 1994, por maioria de votos, apreciando o RECURSO EXTRAORDINÁRIO proveniente do Rio Grande do Sul, declarou a \"... inconstitucionalidade expressão \"autônomos e administradores\", contida no inciso I do artigo 3º das Lei nº 7.787, de 30 de junho de 1989, ...\", dando fim, assim, às divergências jurisprudências e tornando indevidas as contribuições recolhidas. 05. No decorrer da exigência que resultou a contribuição previdenciária referida, a Requerente, num primeiro plano, conforme já mencionado acima, efetuou depósitos e depois recolhimentos de diversos valores a título de \"Pro-labore\" e recolheu, integralmente, aquelas relacionadas com os \"Autônomos\", tudo conforme relacionado no doc. n° ...., correspondentes aos comprovantes igualmente anexados (docs. n°s .... à ....), os quais totalizam, a quantia de R$ .... (....), quantia atualizada até 04.01.95, e que corresponde à .... (....) de UFIR - UNIDADE FISCAL DE REFERÊNCIA e que a Requerente deseja e quer ver repetida, por indevidamente recolhida aos cofres do INSS, ora Requerido, depois de convertidos os depósitos em receita (docs. .... à ....) e através do contido no campo 8 da GRPS (autônomos), docs. .... à .... . Obviamente, a totalidade dos valores indevidamente recolhidos, além de corrigidos monetariamente, deverá ser acrescida de juros de mora, conforme determinação do próprio CTN. 06. Sintetizando, a presente ação visa obter sentença condenando o Requerido INSS, que foi quem fez a arrecadação indevida da contribuição, a devolver todos os valores recolhidos e devidamente comprovados com os documentos anexados, com a necessária atualização monetária e o acréscimo dos juros de mora a razão de 1% (um por cento) ao mês ou fração. O DIREITO 07. A expressão \"autônomos e administradores\" utilizada pela Lei 7.787/89 é inconstitucional, porquanto pretendeu, com o uso de termos próprios da legislação trabalhista, equiparar sócio-gerente e profissional autônomo à empregado, com o objetivo de se amparar na previsão do art. 195, § 4° e inciso I do art. 154 da Constituição Federal em vigor, o que não lhe era permitido, porquanto reservada a utilização à lei complementar. A propósito, a recente decisão do Plenário do SUPREMO TRIBUNAL FEDERAL, no RECURSO EXTRAORDINÁRIO já acima mencionado, aclareando a então pendência e disciplinando a matérias, tem a EMENTA seguinte: \"INTERPRETAÇÃO - CARGA CONSTRUTIVA - EXTENSÃO. Se é certo que toda interpretação traz em si carga construtiva, não menos correta exsurge a vinculação à ordem jurídico-constitucional, o fenômeno ocorre a partir das normas em vigor, variando de acordo com a formação profissional e humanística do intérprete. No exercício gratificante da arte de interpretar, descabe \"inserir na regra de direito o próprio juízo - por mais sensato que seja - sobre a finalidade que \"conviria\" fosse por ela perseguida\" - Celso Antônio Bandeira de Mello - em parecer inédito. Sendo o Direito uma ciência, o meio justifica o fim, mas não este aquele. CONSTITUIÇÃO - ALCANCE POLÍTICO - SENTIDO DOS VOCÁBULOS - INTERPRETAÇÃO. O conteúdo político de uma Constituição não é conducente ao desprezo do sentido vernacular das palavras, muito menos ao de técnico, considerados institutos consagrados pelo Direito, Toda ciência pressupõe a adoção escorreita linguagem, possuindo os institutos, as expressões e os vocábulos que a revelam conceito estabelecido com a passagem do tempo, quer por força de estudos acadêmicos quer, no caso do Direito, pela atuação dos Pretórios. SEGURIDADE SOCIAL - DISCIPLINA - ESPÉCIES - CONSTITUIÇÕES FEDERAIS - DISTINÇÃO. Sob a égide das Constituições de 19334, 1946 e 1947, bem como da Emenda Constitucional nº 1/69, teve-se a previsão geral do tríplice custeio, ficando aberto campo propício a que, por norma ordinária, ocorresse a regência das contribuições . A Carta da República de 1988 inovou. Em preceitos exaustivos - incisos I, II e III do artigo 195 - impôs contribuições, dispondo que a lei poderia criar novas fontes destinadas a garantir a manutenção ou expansão da seguridade social, obedecia regra do artigo 154, inciso I, nela inserta (4° do artigo 195 em comento). CONTRIBUIÇÃO SOCIAL - TOMADOR DE SERVIÇOS - PAGAMENTOS A ADMINISTRADORES E AUTÔNOMOS - REGÊNCIA . A relação jurídica mantida com administradores e autônomos não resulta de contrato de trabalho e, portanto, de ajuste formalizado á luz da Consolidação das Leis do Trabalho. Daí a impossibilidade de se dizer que o tomador dos serviços qualifica-se como empregador e que a satisfação do que devido ocorra via folha de salários. Afastando o enquadramento no inciso I do artigo 195 da Constituição Federal, exsurge a desvalia constitucional da norma ordinária disciplinadora da matéria . A referência contida no 4º artigo 195 da Constituição Federal ao inciso I do artigo 154 nela insculpido, impõe a observação de veículo próprio - a lei complementar. Inconstitucionalidade do inciso I do artigo 3º da Lei nº 7.787/89, no que abrangido o que pago a administradores e autônomos. Declaração de inconstitucionalidade limitada pela controvérsia dos autos, no que não envolvidos pagamentos a avulsos.\" Do voto do Relator, Ministro MARCO AURÉLIO, os seguintes trechos, transcritos com a vênia necessária e com o objetivo de melhor ilustrar o pedido : \"... Acontece que a Corte de origem teve como compreendido na cláusula concernente à obrigatoriedade de os empregadores contribuírem com base na folha de salários, o que pago a administradores e autônomos. Analise-se, portanto, o real alcance do texto do inciso do artigo 195, no que, repita-se, alude a \"empregadores a folha de salários\". Sempre soube dedicada a expressão empregadores\" para qualificar aqueles que mantém, como prestadores de serviços, relação jurídica regida pela Consolidação das Leis do Trabalho e este enfoque restou assentado por esta Corte quando, defrontando-se com ação direta de inconstitucionalidade movida pelo Procurador da República contra preceitos da Lei nº 8.112, de 11 de dezembro de 1991, Lei do \"Regime Único\", afastou a pertinência do artigo 114 da Constituição Federal, que define a competência da Justiça do Trabalho para julgar controvérsias a envolver empregadores e trabalhadores. Na oportunidade, declarou-se competir não a Justiça do Trabalho, mas à Justiça Federal, julgar as lides que envolvam a União e os servidores públicos que a ela prestam serviços sob a égide daquele Regime, leve-se presente que, não sendo o liame regido pela Consolidação das Leis do Trabalho, impossível é cuidar-se da figura do empregador. Refiro-me ao que decidido na ocasião, contra o meu voto, pelas razoes que expus, na ação direta de inconstitucionalidade nº 492, relatada pelo Ministro Carlos Velloso, cujo acórdão foi publicado no Diário da Justiça de 12 de março de 1993. Destarte, já no que o inciso I do artigo 195 revela contribuição devida pelos empregadores, procede a pretensão recursal. A teor do artigo 2º da Consolidação das Leis do Trabalho, considera-se empregador a empresa individual coletiva que, assumindo os riscos da atividade econômica, admite, assalaria e dirige a prestação pessoal dos serviços. O vínculo empregatício pressupõe, em si, a dependência do prestador dos serviços. Se de um lado a econômica e a técnica não são indispensáveis à configuração do fenômeno, de outro há de se fazer presente a jurídica, a revelar submissão do prestador dos serviços ao tomador, sem a qual não se pode dizer da existência de contrato de trabalho regido, pela Consolidação das Leis do Trabalho e, portanto, das figuras de empregado e de empregador. Administradores e autônomos não estão sujeitos a essa subordinação, tal como definida pela ordem jurídica em vigor e corroborada de forma uníssona, por doutrina e jurisprudência. Os primeiros, no que não mantenham contrato de trabalho e portanto, não sejam administradores-empregados, confundem-se com o próprio empregador, e os segundos, os autônomos, atuam de modo independente, ou seja, de acordo com o próprio vocábulo que os distingue, com autonomia. Em relação a eles, não cabe evocar a existência de relação jurídica a envolver a figura do empregador. A isto, soma-se que não estão abrangidos na definição de empregados os próprios administradores da pessoa jurídica que toma os serviços e aqueles que lhe prestam estes últimos com autonomia, porquanto, segundo o artigo 3º da Consolidação das Leis do Trabalho, empregado é toda pessoa natural que presta serviço de natureza não eventual e mediante salário. É certo que determinadas profissões liberais vem cedendo integrantes ao campo trabalhista. É o que ocorre, por exemplo, com os advogados. Durante um bom espaço de tempo era raro encontrar um profissional da advocacia empregado. Hoje a atividade está um pouco proletarizada, talvez por força do grande numero de Faculdades de Direito. Muitos são os bacharéis em direito e, frente à competividade, nem sempre é dado preservar as características nobilizantes do munnus de defender e propugnar pela observância do devido processo legal. Daí caminhar-se para a generalização é passo demasiadamente largo, a implicar o embaralhamento de conceitos jurídicos, olvidando-se que a lei nº 4.215/63 - o Estatuto dos Advogados - define a contraprestação devida como honorários - artigo 96 - que atue o advogado individualmente, quer em sociedade de advogados - artigo 77. Como então, dizer-se que aquele que remunera autônomo, como é geralmente o advogado, deste é empregador e o faz mediante salário, como se no campo de direitos e obrigações ombreasse com os empregados tal como definidos no diploma de regência que é a Consolidação das Leis de Trabalho? Poderia fazer desfilar neste julgamento tantos outros profissionais liberais e, portanto, autônomos, como são os representantes comerciais que a própria Lei nº 1.986/65, no campo pedagógico, indica como autônomos, cogitando da figura do tomador dos serviços como representado, e não empregador, e da prestação por este devida a encerrar o gênero remuneração e não a espécie salário. Falaria sobre o médico, o dentista que também os cidadãos comuns remuneram, sem que assumam a posição de empregadores ou confeccionem folha de salários. Creio que estou dispensado dessa enfadonha missão. ... Tenha-se presente agora a base de incidência da contribuição devida pelos empregadores, no que interessa ao desfecho da controvérsia. O inciso do artigo 195 cuida não de remuneração, não de folha de pagamento, mas de folha de salários. Creio que ninguém ousa caminhar no sentido da aplicação do que se contém, sob o ângulo do salário, a consubstanciar garantia, no artigo 7º da Constituição Federal, a administradores e autônomos. Ninguém compreende, por exemplo, que se diga da irredutibilidade do que percebido por estes. Isto decorre do simples fato de não se ter o envolvimento, na espécie, de salário tal como definido pela melhor doutrina e distinguido pela própria Carta em vigor. Para Amauri Mascaro Nascimento, salário é o pagamento efetuado pelo empregador (sujeito ativo) ao empregado (sujeito passivo), para que possa aproveitar o trabalho dessa pessoa, sem que necessariamente o faça : à obrigação de pagar o salário corresponde o direito de contar com o trabalhador em ocasiões normais. Russomano, sopensando o caráter sinalagmático e comutativo que reveste o contrato de trabalho, entende o vocábulo como a significar a contraprestação devida pelo empregador, em face do serviço desenvolvido pelo empregado. Catharino não discrepa de tais posições. Salienta que \"o salário , em sentido escrito, é aquele devido ao empregado por estar realmente trabalhando ou por estar à disposição do empregador, situação equiparada por lei a prestação efetiva de serviços. O salário em lato sentido é aquele devido ao empregado quando estiver inapto para trabalhar, estiver impedido de fazê-lo, ou ainda, quando a lei ao mesmo tempo lhe faculta não trabalhar, assegurando-lhe a percepção parcial correspondente ao período de inatividade\". Na mesma direção temos Evaristo de Morais Filho e inúmeros juslaboralistas que se debruçam sobre a matéria . Descabe dar a uma mesma expressão - salário - utilizada pela Carta relativamente a matérias diversas, sentidos diferentes, conforme os interesses em questão. Salário, tal como mencionado no inciso I do artigo 195, não pode se configurar como algo que descreve do conceito que se lhe atribui quando se cogita, por exemplo, da irredutibilidade salarial - inciso VI do artigo 7º da Carta. Considere-se que , na verdade, a Lei ordinária mesclou institutos diversos ao prever a contribuição. Após alusão, no capitulo do artigo 3º, a expressão utilizada na própria Carta Federal - folha de salário - ao versar sobre o que pago aos administradores, avulsos e autônomos, referente a remuneração, talvez mesmo pelo fato de o preceito a que se atribui a pecha de inconstitucional englobar, também, os seguros empregados. Desconheceu-se que salário remuneração não são expressões sinônimas. Uma coisa é a remuneração, gênero do qual salário, vencimentos, soldos, subsídio, pro-labore e honorários são espécies. Seria fácil dar-se à previsão constitucional em discussão o alcance sustentado pelo Instituto, no que se fugiria até mesmo da necessidade de batizar-se, de maneira precisa e clara, as bases de incidência das contribuições sociais. Suficiente seria, ao invés de utilizar-se a expressão \"folha de salários \"empregador\", aludir-se ao tomador dos serviços e à remuneração por este satisfeita. Com acerto, enquadraram-se a matéria constitucionalistas e tributaristas, dentre os quais destaco Ives Gandra Geraldo Ataliba, Ruy Barbosa Nogueira e a também professora Misabel Abreu Machado Derci. Esta última emitiu parecer sobre a contribuição social incidente sobre a remuneração e pro-labore pagos à autônomos e administradores. De forma proficiente, apantou a diferença entre o vocábulo \"empresa\" e o vocábulo \"empregador\", afirmando que o uso das expressões \"empregador\" e \"folha de salários\", contidas na Carta de 1988, exclui as relações de trabalho não subordinado, como as que envolvam autônomos em geral e administradores. Aduziu, ainda, que as Constituições brasileiras sempre usaram os termos empregador e salário no sentido próprio e técnico em que encontrados no Direito do Trabalho, o que, aliás, está consagrado jurisprudencialmente, já disse, linhas atrás, que está em tela uma ciência. Assim enquadrado o Direito, o meio justifica o fim, mas não este àquele. Compreendo as grandes dificuldades de caixa que decorrem do sistema de seguridade social pátrio. Contudo, estas não podem ser potencializadas, a ponto de colocar-se em plano secundário a segurança, que é o objetivo maior de uma Lei Básica, especialmente no embate cidadão Estado, quando as forças em jogo exsurgem em descompasso. Atende-se para a advertência de Carlos Maximiliano, isto ao dosar-se a carga construtiva, cuja existência, em toda interpretação, não pode ser negada : \"Cumpre evitar não só o demasiado apego à letra dos dispositivos , como também o excesso contrário , o de forçar a exegese e deste modo encaixar na regra escrita, graças a fantasia do hermeneuta, as teses pelas quais se apaixonou, de sorte que vislumbra no texto idéias apenas existentes no próprio célebre, o no sentir individual, desvairado por ojerizas e pendores, entusiasmos e preconceitos\". - Hermenêutica e Aplicação do Direito. E. Globo, Porto Alegre - segunda edição, 1933, página 118. E realmente assim o é . Conforme frisado por Celso Antonio Bandeira de Mello, não cabe, no exercício da arte de interpretar , \"inserir na regra de direito o próprio juízo - por mais sensato que seja - sobre a finalidade que \"conviria\" fosse por ela perseguida\" - parecer inédito. As remunerações pagas a administradores e autônomos não estão compreendidos o inciso I do artigo 195 da Constituição Federal. Se antes da Carta de 1988 era possível a disciplina mediante lei ordinária, isto ocorria frente a norma geral que apenas consagrava a tríplice fonte de custeio. A partir de 1988, com a previsão explícita e fechada sobre a incidência das contribuições devidas pelos empregadores, considerados o faturamento, o lucro e a folha de salários, a introdução de uma nova contribuição somente poderia vir à balha pelo mecanismo imposto em face da remissão do § 4º do artigo 154, inciso I. Ao legislador estava vedado dispor, via diploma ordinário, sobre a matéria. Por isso mesmo, não foram recepcionados, diante da manifesta incompatibilidade, os preceitos que antecederam a Lei nº 7.787/89. Pouco importa que esta tenha implicado, tão somente, a majoração de percentuais até então observados, pois o defeito precede o exame da extensão da norma. Trata-se de uma lei ordinária e não complementar. Não vinga assim o que sustentado pelo Instituto, em memorial subscrito pelo Dr. Ivan Ferreira de Souza, no sentido de o preceito do inciso I do artigo 195 agasalhar não só o salário propriamente dito, como também a remuneração pertinente aos autônomos, contribuintes individuais, sócios-gerentes, e quotistas que recebem pro-labore, administradores, etc. O preceito não tem contornos tão largos. \"... - Grifos do original. Acórdão na íntegra anexado como documento de nº 064. 08. Sendo inconstitucional como o efetivamente o é, a Lei 7.787/89 e no correspondente às expressões \"autônomos\" contida no inciso I, do artigo 3º da mesma, todas as exibilidades efetuadas e que determinaram os recolhimentos efetuados, o foram, data vênia, indevidamente, porquanto e como o próprio SUPREMO TRIBUNAL FEDERAL já asseverou, ela é nenhuma, por NULA: \"por ser nula e consequentemente ineficaz, reveste-se de absoluta inaplicabilidade. Falecendo-lhe legitimidade constitucional, a lei se apresenta desprovida de aptidão para gerar e operar qualquer efeito jurídico. \"Sendo inconstitucional, a regra jurídica é nula (RTJ 102/671).\" - RE 149955-9, de São Paulo, Plenário, Acórdão publicado no DJU de 03.09.93, Emendário nº 1715-2, Relator Ministro CELSO BANDEIRA DE MELLO, unânime. 09. Decorrência lógica e natural, pois, que os valores arrecadados Requerido - INSS, a título de contribuição previdenciária sobre \"pro-labore\" de administradores e sobre retribuição à \"autônomos\" devem e merecem ser repetidos, o que impõe, data vênia, o reconhecimento quanto a ser procedente a presente ação. 10. Quanto à restituição de valores pagos INDEVIDAMENTE, expressamente dispõe o CÓDIGO TRIBUTÁRIO NACIONAL no art. 165, da seguinte forma: \"Art. 165 (Pagamento indevido - Restituição) - O sujeito passivo tem direito, independentemente de prévio protesto, à restituição total ou parcial do tributo, seja qual for a modalidade do seu pagamento, ressalvado o disposto no § 4° do art. 162, nos seguintes casos: I - cobrança ou pagamento espontâneo de tributo ou maior que o devido em face da legislação tributária aplicável, ou da natureza ou circunstâncias materiais do fato gerador efetivamente ocorrido; II - erro na identificação do sujeito do sujeito passivo, na determinação da alíquota aplicável, no cálculo do montante do débito ou na elaboração ou conferência de qualquer documento relativo ao pagamento; III - reforma, anulação, revogação ou rescisão de decisão condenatória.\" No caso concreto, à restituição e pela via de repetição se apresenta indiscutível, \"data venia\", pela declarada inconstitucionalidade e face a comprovação documental dos valores recolhidos a título de \"pro-labore\" e retribuição à \"autônomos\", não possível, inclusive, qualquer alegação quanto à eventual transferência dos respectivos encargos à terceiros, porquanto suportados diretamente pela Requerente ante a própria natureza da exigibilidade reconhecidamente indevida. 11. Quanto à correção monetária dos valores a repetir, além da consideração quanto a representar \"dívida de valor\", existem reiteradas decisões do próprio SUPREMO TRIBUNAL FEDERAL, como pode ser visto das ementas abaixo transcritas: \"Repetição de indébito tributário. Correção monetária. Precedente do STF. Recurso extraordinário provido.\" - (RE- 85928-SP); \"ICM - Repetição de indébito - Correção monetária - Termo inicial. RE conhecido e provido.\" A correção monetária deve ser calculada a partir da data do pagamento do imposto indevido.\" - (RT - 543/290 - RE 92881 - 1º turma - Relator Min. Rafael Mayer). 12. Face ao exposto, requer se digne V. Exa., registrada e autuada a presente, mandar citar, por Mandado, o Requerido INSTITUTO NACIONAL DE SEGURIDADE SOCIAL, na pessoa de seu Superintendente Regional, com endereço na Rua .... n°...., nesta ...., para vir responder, querendo, no prazo legal, aos termos da presente ação , a qual, desde já, requer seja julgada procedente, para o fim especial de, CONDENAR o Requerido INSS, a restituir, pela via de repetição, a totalidade dos valores recolhidos/repetidos indevidamente, a título de Contribuição Previdênciária sobre \"pro-labore\" e retribuição pagas à \"Autônomos\", desde a vigência da indigitada exigência, com a determinação expressa de que, sobre a totalidade, tendo como termo inicial a data de cada recolhimento, incida a correção monetária devida e pelos índices próprios e oficiais aplicáveis na época da devida repetição, mais juros de mora e pela taxa já apontada, e nas verbas de sucumbência (custas processuais e demais encargos e honorários no percentual de 20% - vinte por cento) sobre o valor corrigido da condenação, tudo a fim de que a repetição seja integral e justa. Para as diligências de citação, pede seja o Sr. Oficial de Justiça autorizado a utilizar as prerrogativas constantes do § 2° do art. 172 do C. P. Civil. Para prova do alegado, se necessário, requer-se, desde logo, a juntada de novos documentos e a realização de perícia contábil. Dá à causa, nos termos da previsão constante do inciso I, do artigo 259 do CPC, o valor de R$ .... (....). Termos em que, Pede deferimento. ...., .... de .... de .... .................. Advogado OAB/...', 'texto.png', NULL);
INSERT INTO `textos` (`id`, `nome`, `area_id`, `texto_id`, `status`, `created_at`, `updated_at`, `obs`, `texto`, `avatar`, `nmtexto`) VALUES
(4, 'MANDADO DE SEGURANÇA  C/ PEDIDO DE LIMINAR', 10, 0, 'A', '2025-06-20 19:22:00', '2025-10-01 02:22:51', 'Conceder-se-á mandado de segurança para proteger direito líquido e certo, não amparado por habeas. Quando há direito líquido e certo ameaçado por autoridade pública,lançamento de tributo sem previsão legal ou sem contraditório.Lei 12.016 de 7 de Agosto de 2009, substitui a  antiga 1.533/51. O Mandado de Segurança é uma ação constitucional, o que significa que sua previsão e cabimento estão diretamente na Constituição Federal (Art. 5º, LXIX e LXX), além de ser regulamentado por lei específica (Lei nº 12.016/2009). ', 'EXMO(A). SR(a). DR(a). JUIZ(a) DE DIREITO DA ___ VARA CÍVEL DA COMARCA DE SÃO PAULO DO ESTADO DE SÃO PAULO Requerente, Brasileiro, Aposentado, portador (a) do documento de identidade nº 14.709.984-5, expedida por SSP/SP, inscrito no CPF sob o nº 000.000.000-00, e-mail email@email.com, residente e domiciliado (a) na Rua Endereço, 000, Bairro Vila Bairro, Cidade Cidade, Estado AA, CEP: 000000-000, vem a presença de Vossa Excelência, por intermédio do (a) advogado (a) subscrito (a), cuja procuração segue anexa, propor a presente AÇÃO ORDINÁRIA DE COBRANÇA DE VALORES DE PASEP C/C PEDIDO DE DANOS MATERIAIS em face de, BANCO DO BRASIL S.A, sociedade de econômia mista, inscrito no CNPJ sob o n.º 00.000.000/0001-91, representado para este fim por seu presidente, a ser citado na pessoa de um de seus representantes legais, com endereço situado no SBS Quadra 01 Lote 32 Bloco C - Ed. Sede III, 24º andar, Setor Bancário Sul, Brasília, DF, Brasil, CEP 70073-901, Telefone (061) 31020-000, e-mail presidencia@bb.com.br; I - DA ASSISTÊNCIA JUDICIÁRIA GRATUITA O Autor é pessoa pobre na acepção do termo e não possui condições financeiras para arcar com as custas processuais e honorários advocatícios sem prejuízo do próprio sustento, razão pela qual desde já requer o benefício da Gratuidade de Justiça, assegurados pela Lei nº. 1060/50 e consoante o art. 98, caput, do CPC: Art. 98. A pessoa natural ou jurídica, brasileira ou estrangeira, com insuficiência de recursos para pagar as custas, as despesas processuais e os honorários advocatícios tem direito à gratuidade da justiça, na forma da lei Para tal benefício, junta declaração de hipossuficiência, o qual demonstra a inviabilidade de pagamento das custas judiciais sem comprometer sua subsistência, conforme clara redação do CPC: Art. 99. O pedido de gratuidade da justiça pode ser formulado na petição inicial, na contestação, na petição para ingresso de terceiro no processo ou em recurso. (...) § 3º Presume-se verdadeira a alegação de insuficiência deduzida exclusivamente por pessoa natural. Assim, por simples petição, sem outras provas exigíveis por lei, faz jus a parte Autora, ao benefício da gratuidade de justiça, com fulcro no artigo 5º, LXXIV da Constituição Federal e pelo artigo 98 do CPC, requer seja deferida a gratuidade de justiça a parte Autora. II. PRIORIDADE NA TRAMITAÇÃO DO PROCESSO Diante do exposto, requer a Vossa Excelência que seja concedida prioridade na tramitação do presente processo, nos termos do art. 70 do Estatuto do Idoso, em razão da idade avançada do autor, que conta atualmente com idade 64 anos. A demora na tramitação deste processo poderá acarretar prejuízos irreparáveis ao autor, considerando suas condições de saúde e a necessidade de uma solução célere para a presente demanda. III. LEGITIMIDADE PASSIVA - BANCO DO BRASIL A competência para a administração do PASEP foi transferida para o Banco do Brasil após a promulgação da Constituição Federal de 1988. Antes dessa mudança, os fundos do PASEP não eram individualizados para cada servidor. Em vez disso, os recursos eram agrupados em um fundo comum, sem contas específicas para cada servidor. No entanto, com a promulgação da CF/88, o fundo do PASEP foi transferido para o Fundo de Amparo ao Trabalhador (FAT), marcando um novo capítulo para os servidores que contribuíram para o PASEP antes de 1988.  Considerando tratar-se de valores devidos pela má gestão do Banco Réu, é inquestionável a sua legitimidade, conforme pacificado pelo STJ, no Tema Repetitivo 1150, com a seguinte tese: \"(...) 6. No entanto, no caso dos autos a demanda não versa sobre índices equivocados de responsabilidade do Conselho Gestor do Fundo, mas sobre responsabilidade decorrente da má gestão do banco, em razão de saques indevidos ou de não aplicação dos índices de juros e de correção 1monetária na conta do Pasep. Conclui-se que a legitimidade passiva é do Banco do Brasil S.A. Nesse sentido: AgInt no REsp 1.898.214/SE, Rel. Ministro Francisco Falcão, Segunda Turma, DJe de 29.4.2021; AgInt no REsp 1.867.341/DF, Rel. Ministra Assusete Magalhães, Segunda Turma, DJe de 7.10.2021; REsp 1.895.114/DF, Rel. Ministro Herman Benjamin, Segunda Turma, DJe de 14.4.2021; AgInt no REsp 1.954.954/CE, Rel. Ministra Regina Helena Costa, Primeira Turma, DJe de 25.3.2022; e AgInt no REsp 1.922.275/CE, Rel. Ministro Gurgel de Faria, Primeira Turma, DJe de 29.6.2021. (STJ,, REsp n. 1.895.936/TO, relator Ministro Herman Benjamin, Primeira Seção, julgado em 13/9/2023, DJe de 21/9/2023). Dessa forma, como a ação trata da má-gestão dos valores da conta PASEP da De Cujus, o Banco do Brasil é parte legítima para figurar no polo passivo desta ação. A competência para julgar as ações de revisão do PASEP contra o Banco do Brasil foi definida pelo Superior Tribunal de Justiça (STJ). De acordo com decisões recentes, a competência é estadual, o Banco do Brasil é considerado uma empresa pública de economia mista. Isso significa que ele possui características tanto de uma empresa estatal quanto de uma empresa privada, . Segundo entendimento dos tribunais brasileiros, a relação entre um correntista titular de conta do PASEP e o Banco do Brasil pode ser enquadrada como relação de consumo, o Código de Defesa do Consumidor (CDC) define consumidor como toda pessoa física ou jurídica que adquire ou utiliza produto ou serviço como destinatário final. No caso de serviços bancários, como a manutenção de conta corrente, o correntista é considerado consumidor, pois utiliza os serviços bancários oferecidos pelo Banco do Brasil como destinatário final. IV. DOS FATOS O Autor devidamente qualificado nos autos, após tomar ciência sobre a possibilidade de análise e revisão do saldo de sua conta Pasep, foi possível perceber, com auxílio da ciência da contabilidade, que a correção dos valores depositados na sua conta PASEP, foram irregulares, havendo ausência de correção/créditos em diversos períodos temporais. Desta forma, conclui-se que a instituição financeira Ré não promoveu a devida administração e correção do PASEP ao longo do período functional do autor, resultando em perda material, também conhecida como dano material ou prejuízo material, é um conceito jurídico que se refere a qualquer diminuição patrimonial sofrida por uma pessoa em decorrência de um ato ilícito praticado por outra. Em outras palavras, é a perda financeira ou a redução do patrimônio de alguém causada por um dano. Os extratos juntados aos autos demonstram essa condição. Não poderia o Requerente ter um saldo e valores diminutos, é inegável que o Brasil passou por um período de hiperinflação. Essa fase turbulenta da economia brasileira marcou profundamente a vida da população e deixou sequelas duradouras. Para a constatação e aclaramento dos dados aqui citados foi gerado uma planilha com lançamentos provinientes das microfichas e extrato da conta do Pasep do autor, documentos em anexo, requerido junto ao réu Banco do Brasil, documento em anexo. Portanto, fica evidenciado que os valores depositados relativos aos programas PASEP, foram mal geridos pela instituição financeira Ré, que era responsável pela recomposição do saldo. Assim, pretende com a presente ação garantir seu direito à correção dos valores do PASEP, de acordo com índices legais, bem como, restituição das diferenças dos últimos anos e obviamente o recebimento. V. DO DIREITO A - PASEP - Programa de Formação do Patrimônio do Servidor Público A Lei Complementar Federal nº. 8/1970 criou o Programa de Formação do Patrimônio do Servidor Público - PASEP, abrangendo os Servidores Públicos de todos os entes federativos, como se nota no artigo 4º da referida LC: Art. 4º - As contribuições recebidas pelo Banco do Brasil serão distribuídas entre todos os servidores em atividade, civis e militares, da União, dos Estados, Municípios, Distrito Federal e Territórios, bem como das suas entidades da Administração Indireta e fundações, observados os seguintes critérios: (...)Parágrafo único - A distribuição de que trata este artigo somente beneficiará os titulares, nas entidades mencionadas nesta Lei Complementar, de cargo ou função de provimento efetivo ou que possam adquirir estabilidade, ou de emprego de natureza não eventual, regido pela legislação trabalhista. Com o advento da Constituição Federal de 1988, a destinação dos recursos do PIS - PASEP foi modificada, passando a ter outros fins, quais sejam, o financiamento do programa de seguro-desemprego e o abono salarial. Nesse sentido: Art. 239. A arrecadação decorrente das contribuições para o Programa de Integração Social, criado pela Lei Complementar nº 7, de 7 de setembro de 1970, e para o Programa de Formação do Patrimônio do Servidor Público, criado pela Lei Complementar nº 8, de 3 de dezembro de 1970, passa, a partir da promulgação desta Constituição, a financiar, nos termos que a lei dispuser, o programa do seguro-desemprego e o abono de que trata o § 3º deste artigo. A Constituição Federal garantiu o patrimônio acumulado do Programa de Integração Social e do Programa de Formação do Patrimônio do Servidor Público, inclusive mantendo-se os critérios de saque nas situações previstas nas leis específicas, com exceção da retirada por motivo de casamento. Porém, parece que o Banco Réu em algum momento suprimiu ou não creditou valores e correções, que mesmo com todo o período funcional, anos de trabalho, não recebeu o que era seu de direito referente a seu periodo laboral, conforme microfichas , documentos em anexo. O Código Civil prevê que: Art. 186. Aquele que, por ação ou omissão voluntária, negligência ou imprudência, violar direito e causar dano a outrem, ainda que exclusivamente moral, comete ato ilícito. Art. 927. Aquele que, por ato ilícito (arts. 186 e 187), causar dano a outrem, fica obrigado a repará-lo. Destarte, deve a Ré reparar os danos causados ao Autor, teve valores relativos ao PASEP, não creditados, ou extraídos indevidamente, além da ausência de rendimentos estabelecidos pelo Conselho Diretor do programa, o que gerou sem dúvida prejuízo material. Experimenta o dano, como prova o saldo apresentado pelo Banco do Brasil em comparativo ao cálculo elaborado, levando em consideração os encargos que são devidos por Lei. Os Tribunais Pátrios têm decidido em situações análogas: APELAÇÃO CÍVEL. AÇÃO ORDINÁRIA QUE VISA CONTESTAR A GESTÃO DOS VALORES DEPOSITADOS NA CONTA VINCULADA AO PASEP. CORREÇÃO MONETÁRIA DO SALDO DA CONTA DO PIS /PASEP. RECOMPOSIÇÃO E RESTITUIÇÃO DE VALORES QUE ALEGA DESFALCADOS DA CONTA DO BENEFICIÁRIO. PRELIMINAR DE LEGITIMIDADE DO BANCO DO BRASIL. ACOLHIDA. SENTENÇA ANULADA. RECURSO PROVIDO. 1. Consoante assentado pelo Superior Tribunal de Justiça no Tema 1.150, julgado pela sistemática dos recursos repetitivos, o Banco do Brasil é parte legítima para figurar no polo passivo de ações judiciais que discutem a gestão de valores depositados em contas do PASEP. 2. Diante da tese fixada sob o rito dos recursos especiais repetitivos, de rigor declarar a nulidade da sentença que extinguiu a ação, sem resolução do mérito, sob o fundamento de ilegitimidade passiva do Banco do Brasil, bem como determinar o retorno dos autos à origem para o seu regular processamento. 3. Preliminar de legitimidade acolhida. Sentença desconstituída. Recurso provido. (TJ-AC - Apelação Cível: 0710298-08.2020.8.01.0001 Rio Branco, Relator: Desª. Waldirene Cordeiro, Data de Julgamento: 26/11/2023, Segunda Câmara Cível, Data de Publicação: 26/11/2023); AGRAVO DE INSTRUMENTO – AÇÃO DE COBRANÇA DE PASEP – PRELIMINARES DE ILEGITIMIDADE PASSIVA, INCOMPETÊNCIA DA JUSTIÇA ESTADUAL E PRESCRIÇÃO – AFASTADAS – TESE FIRMADA NO TEMA 1150 DO STJ – INVERSÃO ÔNUS DA PROVA – POSSIBILIDADE – APLICAÇÃO DO ARTIGO 373, § 1º, CPC – MATÉRIA PRECLUSA – DECISÃO MANTIDA – RECURSO CONHECIDO E DESPROVIDO. No julgamento do Tema 1150 do STJ, firmaram-se as as seguintes teses: \"i) o Banco do Brasil possui legitimidade passiva ad causam para figurar no polo passivo de demanda na qual se discute eventual falha na prestação do serviço quanto a conta vinculada ao Pasep, saques indevidos e desfalques, além da ausência de aplicação dos rendimentos estabelecidas pelo Conselho Diretor do referido programa; ii) a pretensão ao ressarcimento dos danos havidos em razão dos desfalques em conta individual vinculada ao Pasep se submete ao prazo prescricional decenal previsto pelo artigo 205 do Código Civil; e iii) o termo inicial para a contagem do prazo prescricional é o dia em que o titular, comprovadamente, toma ciência dos desfalques realizados na conta individual vinculada ao Pasep\", de modo que o Banco do Brasil S/A é parte legítima para figurar no polo passivo da ação de cobrança de Pasep, a competência é da justiça estadual, a prescrição da pretensão é decenal e seu termo a quo é a data do saque do saldo encontrado, quando o titular toma ciência dos desfalques. Mesmo que não fosse reconhecida a preclusão e a aplicação do CDC, ainda que por fundamento diverso, a inversão do ônus da prova se imporia com fundamento no 373, § 1º, do Código de Processo Civil. (TJ-MS - Agravo de Instrumento: 1405360-52.2022.8.12.0000 Campo Grande, Relator: Des. Amaury da Silva Kuklinski, Data de Julgamento: 14/12/2023, 3ª Câmara Cível, Data de Publicação: 15/12/2023) B - PRAZO PRESCRICIONAL DECENAL No Julgamento do tema 1150 do STJ, firmou-se o entendimento que o prazo prescricional para pretensão ao ressarcimento dos danos havidos em conta individual do PASEP, é o decenal previsto pelo art. 205 do Código Civil. C - TERMO INICIAL PARA CONTAGEM DO PRAZO Também, tomou-se entendimento no Julgamento do tema 1150 do STJ, que o termo de contagem inicial do prazo prescricional é o dia em que o titular, comprovadamente, toma ciência dos desfalques realizados na conta PASEP (art. 189 do Código Civil). V. EXIBIÇÃO DE DOCUMENTOS A instituição financeira requerida, dever-se-ia apresentar os extratos detalhados e evolução do saldo de todo o período da conta PASEP do Autor, de forma extrajudicial com simples pedido, contudo, os documentos apresentados foram apresentados em cópias de Microfilmagens em muitas vezes apagados e ou de dificil leitura, verdadeiros alfarabios, documentos de dificil leitura e interpretação. Onde da sua solicitação e entrega decorrem-se 5 meses, pois sua solicitação deu-se em 27/12/2023 e o recebimento em 25/04/2021. Tal informação só denota ao dificil acesso à informação ao Autor, onde o Banco Reu estabelece periodo com dilação temporal injustificavel, o torna-se necessário os pedidos Judiciais, ante a persistente ação do Banco Réu em fornecer os documentos de apuração desses valores de forma precária. A totalidade dos registros solicitados, necessarios, só foi entregue em documento posterior , extrato, em 10/07/2024, ou seja 8 meses após solicitação inicial. Conforme documento em anexo denominado de PASEP extrato. O Código de Processo Civil, prevê: Art. 396. O juiz pode ordenar que a parte exiba documento ou coisa que se encontre em seu poder. Art. 397. O pedido formulado pela parte conterá: I - a descrição, tão completa quanto possível, do documento ou da coisa, ou das categorias de documentos ou de coisas buscados; II - a finalidade da prova, com indicação dos fatos que se relacionam com o documento ou com a coisa, ou com suas categorias; III - as circunstâncias em que se funda o requerente para afirmar que o documento ou a coisa existe, ainda que a referência seja a categoria de documentos ou de coisas, e se acha em poder da parte contrária. Art. 398. O requerido dará sua resposta nos 5 (cinco) dias subsequentes à sua intimação. Parágrafo único. Se o requerido afirmar que não possui o documento ou a coisa, o juiz permitirá que o requerente prove, por qualquer meio, que a declaração não corresponde à verdade. Art. 399. O juiz não admitirá a recusa se: I - o requerido tiver obrigação legal de exibir; II - o requerido tiver aludido ao documento ou à coisa, no processo, com o intuito de constituir prova; III - o documento, por seu conteúdo, for comum às partes. Art. 400. Ao decidir o pedido, o juiz admitirá como verdadeiros os fatos que, por meio do documento ou da coisa, a parte pretendia provar se: I - o requerido não efetuar a exibição nem fizer nenhuma declaração no prazo do art. 398 ; II - a recusa for havida por ilegítima. Parágrafo único. Sendo necessário, o juiz pode adotar medidas indutivas, coercitivas, mandamentais ou sub-rogatórias para que o documento seja exibido. Portanto, frente a possibilidade prevista no CPC, deve a instituição Ré ser intimada a apresentar os extratos, sob pena de ser tido como referência em julgamento os cálculos apresentados na inicial. VI - DA INVERSÃO DO ÔNUS DA PROVA O direito do Autor de receber os valores do Pasep decorre da constituição Federal 1988, em seu artigo 7º, inciso XX, que garante aos trabalhadores urbanos e rurais o FGTS e outros benefícios previstos em lei. A Lei nº 8.036/90, que dispõe sobre o FGTS, não traz disposições específicas sobre a transferência dos valores do Pasep em caso de falecimento do titular. No entanto, a natureza alimentar do benefício e os princípios da dignidade da pessoa humana e da proteção à família, consagrados na Constituição Federal, autorizam a transmissão dos valores do Pasep aos dependentes do falecido. Como dispõe o artigo , inc. do , é direito básico do consumidor: “a facilitação da defesa de seus direitos, inclusive com a inversão do ônus da prova, a seu favor, no processo civil, quando, a critério do juiz, for verossímilhança a alegação ou quando for ele hipossuficiente, segundo as regras ordinárias de experiências.” Por oportuno, trazemos à baila o ensinamento de Plínio Lacerda Martins, in “Anotações ao . Conceito e noções básicas. DP & A Editora. RJ. 2001, p.27”: “Tendo em vista que o , no artigo ,VIII, prevê como direito básico do consumidor o direito à inversão do ônus da prova no processo quando a alegação for verossímil, facilitando assim a defesa dos direitos dos consumidores, e que esta inversão ao nosso juízo é ope judicis, não se justifica então a não-inversão do ônus da prova quando comprovada a verossimilhança ou mesmo a hipossufiência.” Saliente-se que no caso em foco, a Autor, sendo consumidor hipossuficiente e verificando-se a veracidade das alegações (prova documental que segue em anexo), detém então os requisitos para que o Douto Magistrado se digne conceder a Inversão do ônus da prova em favor do Autor. VII. DOS CÁLCULOS Diante dos dados apurados que puderam ser recuperados , do histórico financeiro economico, foi gerado um demosntrativo em planilha de cálculo, documento exibido e em anexo : Cita-se que o presente demonstrativo baseou-se em documentos de microfilmagens, extrato, fontes de dados oficiais do Banco Central do Brasil, Leis específicas que norteam a tese bem como baseado-se na jurisprudencia contemporanea e base de resoluções de tribunais brasileiros. A revisão do PASEP com a aplicação dos expurgos é importante por diversos motivos: Garantia de direitos: Assegura que os trabalhadores recebam o valor correto de seus recursos, corrigidos pela inflação. Justiça social: Corrige uma injustiça histórica, causada pelos planos econômicos que desvalorizaram a moeda. Fortalecimento da economia: Ao garantir que os trabalhadores tenham acesso aos recursos a que têm direito, contribui para o fortalecimento da economia. Os expurgos no PASEP é uma forma de corrigir as perdas inflacionárias causadas por planos econômicos passados, garantindo que os trabalhadores recebam o valor justo de seus recursos. A revisão do PASEP é um direito dos trabalhadores. VIII. DOS DANOS MORAIS Valor da Indenização por Prejuízos Causados por Má Administração Bancária: Uma Análise Complexa, o valor da indenização a ser pleiteada em um caso de prejuízos causados por má administração bancária, como créditos incorretos, é uma questão complexa e que varia de acordo com cada caso concreto. Com isso Fatores que influenciam o valor da indenização são eles Natureza do prejuízo: omitido retirado do patrimônio do autor valores que visivelmente poderia ter contribuído na vida do autor na realização de tarefas e sonhos que evidentemente não podem ser mensurados ou calculados, a dor causada pela falta é única, portanto cada um tem a sua e assim intangivelmente calculada. Danos materiais: Perda financeira direta, como valores indevidamente debitados ou não creditados na conta em muito sem a anuência do autor titular da conta. Essa conta ao longo da Gestão do réu Banco do Brasil, esteve as margens de atuação do autor, haja vistos que durante a mais de duas décadas que o réu geriu a conta, não há registros de repasses, relatórios para o autor, o banco réu agiu nesse período como proprietário e não administrador, sendo que contemporaneamente pode-se constatar a péssima administração executada. Danos morais: Sofrimento, angústia, constrangimento e outros danos psicológicos causados pela situação, não há em se falar na equidade do relacionamento, quando um cidadão em relação direta de cliente com uma instituição do porte do Banco Do Brasil, que tem como objetivo principal contribuir para o crescimento econômico, industrial, comercial e social do Brasil , vê sua conta e seus valores negados ou mesmo alterados por quem dever-se protege-los. Duração do problema: A gestão do atos falhos, realizados pelo Banco réu, pendura bem antes da ultima mudança de moeda, revela portanto ser o Banco réu participante de décadas da influência direta sobre os valores. Conduta do banco: O banco réu diante da reclamação do cliente mostra-se inerte, passivo , como não tivesse nenhuma responsabilidade sobre até aqui citado. A atitude demonstra má-fé ou negligência. A passividade, em um sentido jurídico, está intrinsecamente ligada à ideia de inércia, omissão ou falta de ação, Omissão: Aquele que, por ação ou omissão voluntária, negligência ou imprudência, violar direito e causar dano a outrem, ainda que exclusivamente moral, comete ato ilícito. (Art. 186 do Código Civil). Dever de agir: é um conceito que permeia diversas áreas do conhecimento, especialmente a filosofia, o direito e a ética. Ele se refere à obrigação moral ou legal que uma pessoa tem de realizar determinada ação, em detrimento de outras, em determinadas circunstâncias. Em determinadas situações, a lei impõe a obrigação de agir, sob pena de responsabilidade. A definição do valor da indenização é uma tarefa complexa que exige a análise de diversos fatores e a apresentação de provas que demonstrem o prejuízo sofrido pelo cliente. Diversos tribunais brasileiros já reconheceram o direito dos correntistas à indenização por danos morais e/ou perdas e danos em casos de débitos em atraso em contas do PASEP não resgatadas. Alguns exemplos: STJ: \"O Banco réu, por sua negligência e imperícia na gestão da conta PASEP do autor, causando-lhe transtornos e angústia, deve indenizá-lo por danos morais.\" (REsp 1.504.478/RS) TJSP: \"O banco falhou em seu dever de informação e gestão da conta PASEP do autor, causando-lhe prejuízos financeiros e sofrimento psicológico. Deve, portanto, indenizá-lo por danos morais e perdas e danos.\" (Apelação Cível 1.000.000-00/SP) É importante ressaltar que o valor da indenização será definido pelo juiz, após a análise das provas e dos argumentos apresentados pelas partes, segue este para formação de juízo o valor de R$ 15.000,00, como Danos Morais, haja vistos o descritivo de danos morais, nexos, a característica do ofensor infinitamente superior em relação ao autor, a reincidência do réu, a idade do autor defesa em lei e princípio da proporcionalidade e razoabilidade sem causar o enriquecimento injustificado do correntista, mas sim compatibilizando com os padrões sociais, considerando o valor do dano e a capacidade do banco réu. IX. DOS HONORÁRIOS ADVOCATÍCIOS Diante da complexidade da causa, do tempo despendido e Diligencias ao banco réu para obtenção de documentos, pelo advogado, do valor da condenação e da importância do resultado obtido, requer a condenação do réu ao pagamento, considerando-se o principio da razoabilidade, honorários advocatícios no valor de 20% (vinte por cento) sobre o valor da condenação, nos termos do artigo 85, § 2º, do Código de Processo Civil. X. DOS PEDIDOS Diante o exposto, requer à Vossa Excelência: A - A concessão do benefício da justiça gratuita, por ser a parte autora pessoa sem condições de arcar com as custas, honorários advocatícios e demais despesas processuais, ademais neste momento, sem prejuízo ao sustento próprio e de sua família consoante declaração anexa. B - A citação do Réu para, querendo, ofertar resposta em tempo hábil, sob pena de confissão e revelia; C - A Procedência da Ação, com a condenação do Réu a restituir os valores desfalcados da conta PASEP do autor, no montante de R$ 61.149,69 (Sessenta e um mil cento e quarenta e nove reais e sessenta e nove centavos), já deduzido o que foi recebido, atualizados até a presente data, conforme memória de cálculos (anexo); D - A inversão do ônus da prova e a apresentação dos documentos das microfilmagens adiante especificadas, uma vez que o banco Réu dignou a apresentar a parte Autora as informações que foram solicitadas, de forma segmentada e incompleta, sendo do fato, são documentos comuns às partes, sob pena do disposto no art. 400 do CPC. O Autor tem o direito de ter acesso às microfilmagens dos extratos de todo o período da conta do PASEP, nos termos do citado art. 396 CPC, haja vista que as instituições financeiras devem manter seus arquivos devidamente organizados e catalogados de modo a permitir uma fácil e célere consulta, a teor do disposto no § 1º do art. 1º da Resolução nº 913/84 do BACEN. E - A condenação do Réu ao pagamento das custas e demais despesas processuais, inclusive em honorários advocatícios sucumbenciais, que deverão ser arbitrados por este Juízo, conforme norma do artigo 85 do CPC expressos como sugestão de 20%; F - Requer a produção de todos os meios de prova em direito admitidos, notadamente a prova documental, testemunhal e depoimento pessoal do representante do Réu, sob pena de confissão ficta. G - Em homenagem ao princípio da razoável duração do processo, o Promovente opta pela não realização de audiência conciliatória (CPC, art. 319, inc. VII), haja vista a escassa possibilidade de transação judicial entre os litigantes. Dá-se à causa o valor de R$ 0,00 (valor extenso). Nestes termos, pede e espera deferimento.', 'texto.png', NULL),
(5, 'API_ANA', 20, 0, 'A', '2025-06-27 01:39:00', '2025-06-27 01:39:00', 'Documentação da API – Envio de Dados à ANA', 'Visão Geral, Funcionalidades Principais, Automação com Docker e Cron, E-mails de Confirmação ', 'engenharia.png', NULL),
(6, 'AÇÃO DE COBRANÇA - CONDOMÍNIO', 9, 0, 'A', '2025-06-30 20:08:00', '2025-07-01 21:08:34', 'A principal mudança é que o crédito referente às contribuições de condomínio (ordinárias ou extraordinárias) passou a ser considerado título executivo extrajudicial, conforme o Artigo 784, inciso X, do CPC.', 'EXMO. SR(a) DR(a) JUIZ(a) DE DIREITO DA DA COMARCA DE CIDADE /EST ___________, CNPJ nº __________, com sede na Rua: _________, nº __, Bairro: _________, na Cidade de _________, CEP _____-___, representado por seu síndico __________, vem por meio de seu advogado, que receberá as intimações na Rua: _________, nº __, Bairro: _________, na Cidade de _________, CEP _____-___, e-mail __________, perante Vossa Excelência, propor AÇÃO DE COBRANÇA CONDOMINIAL, com fulcro nos arts. 319 e ss. Do CPC/2015, contra ___________, brasileiro, casado, (profissão), RG nº __________/SSP, CPF nº ___.___.___-__, Nascido em __/__/____, Filiação _________ e _________, Residente na Rua: _________, nº __, Bairro: _________, na Cidade de _________, CEP _____-___, pelas razões que passa a expor: FATOS E FUNDAMENTOS O Réu é proprietário do apartamento nº ___, do Edifício ___________, localizado na Rua: _________, nº __, Bairro: _________, na Cidade de _________, CEP _____-___, sendo o mesmo responsável pelo pagamento da sua fração-ideal das contribuições sindicais. (doc. Anexo) Ocorre que, desde __/__/__, o condômino não paga a sua obrigação para com o condomínio, devendo o montante de R$ ____,__ (__________ reais), referente a 7 (sete) meses de despesas condominiais atrasadas. Requer o autor, por meio desse instrumento, que o réu pague o valor devido, acrescido de juros, multa de 7% sobre o valor total do inadimplemento e correção monetária, tudo conforme o que estabelece a convenção de condomínio, em anexo, e a Lei nº 4.591/1964 no seu art. 12, § 3º, somando também, as parcelas que vencerem no decorrer do processo, cf. art. 323 do CPC/2015. REQUERIMENTOS Requer o conhecimento e a apreciação da presente ação, com designação de audiência de mediação ou de conciliação, sendo o réu citado com, no mínimo, 20 (vinte) dias de antecedência. Não comparecendo o réu à audiência, sem que, com no mínimo 10 (dez) dias de antecedência, tenha peticionado em contrário à autocomposição, pede-se a aplicação de multa de 2% do valor da causa, conforme o art. 334, §§ 5º e 8º, do CPC/2015. Requer que o Réu seja informado que poderá contestar a petição inicial, em até 15 (quinze) dias contatos da audiência de mediação/conciliação, conforme o art. 335 do CPC/2015, e caso não conteste a ação, incorrerá em revelia, conforme o art. 344 do CPC/2015. Espera-se que a ação seja julgada totalmente procedente, condenando o Réu ao pagamento das cotas condominiais vencidas e vincendas, acrescidas de juros, multa e correção monetária, além do pagamento das custas e despesas processuais, bem como os honorários advocatícios. Almeja-se provar o alegado por todos os meios de prova em direito admitidos. Atribui-se à causa o valor de R$ ________. Nestes termos, Pede deferimento. [Local] [data] __________________________________ [Nome Advogado] - [OAB] [UF].', 'texto.png', NULL),
(7, 'ABERTURA DE INVENTÁRIO RITO DE ARROLAMENTO', 1, 0, 'A', '2025-06-30 21:53:00', '2025-09-29 22:56:26', 'Requerimento de abertura de inventário pelo rito de arrolamento, sendo nomeada inventariante a viúva meeira. O falecido não deixou testamento. Apresentado o rol de herdeiros e a relação de bens. Face a cessão de direitos feita pela viúva meeira de sua meação, está gravada com o usufruto vitalício a seu favor, procede-se ao pagamento aos herdeiros.', 'CESSÃO DE QUOTAS DE SOCIEDADE À VISTA Pelo presente instrumento particular de cessão e transferência de quotas sociais, de um lado ................................................................... (nome completo do cedente), residente e domiciliado à ............................................ n.º ........, (endereço completo do cedente), ..............................., RG n.º ............................ (número de identidade do cedente), CIC n.º ..............................., (número do CPF do cedente), sócio quotista da firma .............................................. (denominação da firma ou razão social em que o cedente é sócio), com sede à ................................., (endereço completo de firma ou empresa, cujas quotas sociais estão sendo negociadas), na cidade de ....................., Estado de ...................., (cidade e Estado em que se situa a sede da empresa), CGC n.º ................, (número do CGC da empresa), com contrato social arquivado na Junta Comercial do Estado de ......................................................, sob número ........................ (dados do contrato inicial da empresa) e alterações contratuais sob números ........................, ...................., (citar todas as alterações sociais da empresa, arquivadas na Junta Comercial do respectivo Estado) de ora em diante chamado simplesmente de CEDENTE e, do outro lado, ............................................, (nome completo de quem está adquirindo as quotas), de nacionalidade ......................., de profissão ............................., estado civil ................................, residente e domiciliado à .......................................... n.º ........, (endereço completo de quem está adquirindo as quotas), na cidade de ......................., Estado de ..........................................., RG n.º ...................... (número da identidade de quem está adquirindo as quotas), CIC n.º ............................................., (número do CPF de quem está adquirindo as quotas) (se a aquisição das quotas está sendo realizada por uma outra empresa, a identificação do cessionário será a da empresa adquirente das quotas, naturalmente representada por um dos sócios ou gerentes ou elemento legalmente autorizado, chamado simplesmente de CESSIONÁRIO, têm, entre si, como justo e contratado, o que se segue: 1º - O CEDENTE é detentor, por todos os títulos de direito, de ...................... (quantidade de quotas sociais) quotas sociais, no valor de R$........................ (valor de cada quota, segundo o contratado social ou suas alterações), totalizando R$ a ............................................. (valor total das quotas sociais), consoante contrato social e alterações citadas especificamente no intróito deste instrumento contratual.2º - As respectivas quotas do CEDENTE estão (ou não estão) inteiramente integralizadas (se não estiverem inteiramente integralizadas, citar a quantidade e os valores das que deverão sê-las).3º - (Se houver, no contrato social, direito de preferência pela aquisição de quotas pelos outros sócios). Ofertou CEDENTE as quotas sociais de que era titular aos demais sócios da sociedade, consoante o disposto na cláusula ............ (citar o número da cláusula do contrato social da empresa), sem que os mesmos se interessassem em exercer o seu direito de preferência (ou: abrindo os mesmos mão de seu direito de preferência), conforme correspondência que se anexa a este instrumento, ficando o CEDENTE livre para negociá-las com terceiros.4º - O CEDENTE, por este instrumento, cede ao CESSIONÁRIO as quotas sociais de que é titular, e já integralizadas, pelo valor de R$............................ (valor total da transação das quotas), assim como todos os seus direitos e obrigações contratuais.5º - O CESSIONÁRIO paga, neste ato, através do cheque número .............................. (número do cheque emitido pelo cessionário), emitido contra o Banco .................................. (banco contra o qual o cheque foi emitido), o valor de R$.............................................. (valor total da transação, referido na cláusula 4ª, acima), dando o CEDENTE, por este ato, total e plena quitação de seus haveres, nada mais tendo a reclamar do CESSIONÁRIO a nenhum título, por esta transação.6º - O CEDENTE obriga-se à transferência oficial das quotas da sociedade, transacionadas por este instrumento, até o dia ........ de ............................ de 19........ (dia, mês e ano), ao CESSIONÁRIO, através de alteração contratual que fará elaborar por advogado e que será por ele assinada, juntamente com o outro (ou os demais sócios, se houver mais de um sócio além do CEDENTE), integrando o CESSIONÁRIO no domínio das quotas respectivas e seus direitos e obrigações conseqüentes.7º - O CESSIONÁRIO obriga-se ao arquivamento da alteração contratual, pela cessão e transferência de quotas, até o prazo de 30 (trinta) dias, contados da data da sua assinatura, sob pena de, se não o fazendo, investir o CEDENTE da autorização de fazê-lo, para valer a cessão e transferência diante de terceiros.8º - Declara-se o CESSIONÁRIO inteiramente ciente do estado econômico e financeiro da empresa cujas quotas estão, parcialmente, sendo transferidas e cedidas por este ato, nada podendo alegar, sobre estas situações, para retratar-se ou reverter esta transação.9º - Este ao é celebrado sob a condição expressa de sua irrevogabilidade e irretratabilidade.10º - Para dirimir quaisquer questões que direta ou indiretamente decorrerem deste contrato, as partes elegem o Foro desta Comarca, com renúncia expressa de qualquer outro por mais privilegiado que seja.11º - Para todos os fins e efeitos de direito, os contratantes declaram aceitar o presente contrato nos expressos termos em que foi lavrado, obrigando-se a si, seus herdeiros e sucessores a bem e fielmente cumpri-lo.E por estarem assim ajustados e em perfeito acordo em tudo quanto neste instrumento particular foi lavrado, obrigam-se as partes a cumprir o presente contrato, assinando-o na presença das duas testemunhas abaixo, em .................... (número de vias) vias, de igual teor..............................., ....... de ..................... de ............................................................(assinatura do CEDENTE) ....................................................(assinatura do CESSIONÁRIO) Testemunhas: 1ª - .........................................2ª - .........................................________________________ Observação: O valor da transação, neste contrato, poderá ser maior que o valor das quotas sociais ou menor que elas, quando, então, haverá o ágio ou deságio que beneficia ou leva prejuízo ao cedente como pessoa física.O valor deste contrato, na contabilidade, não aparecerá, salvo na contabilidade do cessionário, se este for pessoa jurídica.', 'texto.png', NULL),
(9, 'DEFESA PRÉVIA', 11, 0, 'A', '2025-06-30 23:39:31', '2025-09-29 18:49:12', 'DESFESA PRÉVIA', 'CESSÃO DE DIREITOS SOBRE IMÓVEIS Por este instrumento particular de cessão de direitos sobre imóveis, de um lado (.....) {nome completo e por extenso do dono do imóvel}, nacionalidade (.....), estado civil(.....) {se casado, o regime do casamento}, profissão (.....), CIC nº (.....), Cédula de Identidade RG nº (.....) {se casado, segue o nome da esposa e sua qualificação}, residentes e domiciliados à Rua (.....) nº (.....), na cidade de (.....), Estado de (.....), de ora em diante chamados simplesmente de CEDENTE, e, de outro lado (.....) {nome completo e por extenso de quem receberá o imóvel}, nacionalidade (.....), estado civil (.....) {se casado, o regime do casamento}, profissão (.....), CIC nº (.....), Cédula de Identidade RG nº (.....) {se casado, segue o nome da esposa e qualificação}, residentes e domiciliados à Rua (.....) nº (.....), na cidade de (.....), Estado de (.....), de ora em diante chamados simplesmente de CESSIONÁRIO, têm, entre si, como justo e contratado o que se segue e que mutuamente acordam: 1º - Por força de contrato de promessa de compra e venda, o CEDENTE tornou-se titular dos direitos aquisitivos do imóvel (.....) {individualizar o imóvel, fornecendo a sua localização, situação, mediações e confrontações, nomes dos vendedores originais e dados do registro {se houver sido registrado} no Cartório de Registro competente}. 2º - Diz o CEDENTE que o imóvel descrito e caracterizado na cláusula anterior se acha livre e desembaraçado de todos e quaisquer ônus judiciais e extrajudiciais, foro, pensão e hipoteca de qualquer natureza, bem como quite de impostos e taxas. 3º - Achando-se, como se acha igualmente pago o preço pactuado no mencionado compromisso de compra e venda, o CEDENTE, por este instrumento particular e na melhor forma de direito, promete e se obriga a ceder e transferir ao CESSIONÁRIO todos os direitos decorrentes daquele contrato, dentro das cláusulas e condições deste instrumento de cessão de direitos. {Se ainda houver parcelas a serem pagas, no compromisso inicial, utilize a cláusula 3ª, com a redação seguinte:} 3º - Achando-se, ainda, o preço pactuado no mencionado compromisso de compra e venda com (.....) {número de parcelas} parcelas ou prestações a pagar, no valor de (.....) {valor por extenso} cada uma, vencíveis a partir de (.....) de (.....) de 19(.....), o CEDENTE, por este instrumento particular e na melhor forma de direito, promete e se obriga a ceder e transferir ao CESSIONÁRIO todos os direitos decorrentes daquele contrato, dentro das cláusulas e condições deste instrumento de cessão de direitos. 4º - O preço certo e ajustado para a cessão é de (.....) (.....) {valor por extenso}, dos quais a importância de (.....) {valor da entrada, transcrito também por extenso} é recebida neste ato, pelo CEDENTE, em moeda corrente {se através de cheque, substituir o \"em moeda corrente\" por \"através de cheque, nº (.....), emitido pelo CESSIONÁRIO contra o Banco (.....)\"}, pelo que o CEDENTE dá a mais geral, rasa e irrevogável quitação para nada mais exigir em relação a ele e a importância de (.....) {valor do saldo, transcrito também por extenso} será paga em (.....) prestações mensais, sem juros, iguais e sucessivas, vencendo-se a primeira prestação de (.....) {valor da prestação} no dia (.....) do mês de (.....) de 19(.....), e as demais em igual dia dos meses subseqüentes {se houver parcelas intermediárias ou outra for a condição do pagamento, incluí-la no contrato, em substituição a esta}. 5º - O pagamento das prestações {ou parcelas} aqui pactuadas será feito na residência do CEDENTE, ou em local onde este indicar, com uma tolerância de até (.....) dias após o respectivo vencimento. {Se houver emissão de nota promissória para representar as parcelas, utilizar como cláusula 5ª a seguinte:} 5º - As prestações mensais, referidas na cláusula 4ª passam a ser representadas por notas promissórias, de emissão e aceite do CESSIONÁRIO, dando-se a elas uma tolerância de (.....) dias após o respectivo vencimento, e permanecerão vinculadas a este instrumento. 6º - No caso de impontualidade no pagamento de qualquer das prestações, pagará o CESSIONÁRIO os juros de mora de 1% {um por cento} ao mês, enquanto perdurar o atraso. 7º - Se o atraso resultar em falta de pagamento de 3 {três} prestações consecutivas, ficará de pleno direito vencida toda a dívida independentemente de aviso ou notificação judicial ou extrajudicial, sujeitando-se o CESSIONÁRIO à cobrança executiva da mesma, acrescida da multa de (.....)% {transcreve por extenso} do valor total do débito, sem prejuízo dos juros moratórios previstos na cláusula anterior. {Se existirem ainda parcelas a serem pagas, no contrato anterior firmado pelo CEDENTE com os vendedores originais, utilizar também a cláusula seguinte:} 8º - As parcelas ou prestações a pagar, decorrentes do compromisso inicial de compra e venda, conforme a cláusula 3ª deste instrumento, serão pagas por (.....) {pelo CEDENTE ou CESSIONÁRIO, conforme ficar pactuado entre as partes}, devendo ser quitadas rigorosamente em dia e sem atraso. {Observação: Se esta cessão for feita com pagamento à vista, não utilizar as cláusulas 4ª e 7ª deste instrumento, substituindo-as pela cláusula 4ª com a redação seguinte: } 4º - O preço certo e ajustado para a cessão é de (.....) (.....) {valor transcrito também por extenso}, valor esse recebido integralmente, neste ato, pelo CEDENTE, em moeda corrente {se em cheque, substituir o \"em moeda corrente\" por \"através do cheque nº (.....), emitido pelo CESSIONÁRIO contra o Banco (.....)\"}, pelo que o CEDENTE dá a mais geral, rasa e irrevogável quitação para nada mais exigir em relação a ele ou à cessão que ora é feita. 9º - O CESSIONÁRIO é, neste ato, imitido na posse do imóvel, ficando a seu cargo, a partir desta data, o pagamento de todos os tributos, taxas e tarifas que incidam ou venham a incidir sobre o referido imóvel. 10º - Correrão por conta do CESSIONÁRIO todas as despesas que forem necessárias para a efetivação da cessão ora prometida, inclusive certidões negativas e todos e quaisquer tributos que onerem ou venham a onerar a presente transação. 11º - O presente instrumento, em todos os seus termos, é feito em caráter irrevogável, obrigando a herdeiros e sucessores das partes contratantes. 12º - A escritura definitiva será realizada tão logo esteja paga a última prestação, e se o CESSIONÁRIO foi obrigado a recorrer aos meios judiciais para obter a sua adjudicação compulsória, pagará ao CEDENTE a multa de (.....) {valor por extenso}, além dos honorários de advogado do CESSIONÁRIO. 13º - As partes elegem o Foro desta cidade para dirimir as questões oriundas deste contrato, com renúncia de qualquer outro, por mais privilegiado que seja. E por estarem as partes, Cedente e Cessionário, em pleno acordo, em tudo quanto se encontra disposto neste instrumento particular, assinam-no na presença das duas testemunhas abaixo em (.....) vias de igual teor e forma, destinando-se uma via para cada uma das partes contratadas neste instrumento. {datar e assinar: cedente, esposa do cedente, cessionário e sua esposa}', 'texto.png', NULL),
(10, 'DECLARAÇÃO DE HIPOSSUFICIÊNCIA ECONOMICA', 10, 0, 'A', '2025-07-27 03:00:00', '2025-08-05 22:43:45', 'DECLARAÇÃO DE HIPOSSUFICIENCIA', 'DECLARAÇÃO DE HIPOSSUFICIENCIA FINANCEIRA Nome , Rg **.***.***-*, CPF sob o nº ***.***.***-** , NIS ***.***.***-**, DECLARO, para todos os fins de direito e sob as penas da lei, que não tenho condições de arcar com as despesas inerentes ao presente processo, sem prejuízo do meu sustento e de minha família, necessitando, portanto, da , nos termos do art. 98 e seguintes da Lei 13.105/2015 (Código de Processo Civil). Requeiro, ainda, que o benefício abranja a todos os atos do processo.', 'texto.png', NULL);
INSERT INTO `textos` (`id`, `nome`, `area_id`, `texto_id`, `status`, `created_at`, `updated_at`, `obs`, `texto`, `avatar`, `nmtexto`) VALUES
(13, 'MANDADO DE SEGURANÇA', 10, 0, 'A', '2025-07-27 03:00:00', '2025-08-05 22:42:23', 'MANDADO DE SEGURANÇA', 'EXMO. SR. DR. JUIZ DE DIREITO DA .....VARA CÍVEL DA COMARCA DE ..... ou EXMO. SR. DR. JUIZ DE DIREITO DA ..... VARA DA FAZENDA PÚBLICA DO ESTADO DE SÃO PAULO Nome, qualificação, por seu advogado e bastante procurador , vem, respeitosamente, à presença de V. Exa., com fundamento no inciso LXIX do artigo 5º da Constituição Federal e na Lei no. 12.016 impetrar MANDADO DE SEGURANÇA contra ato do Sr. Delegado Regional Tributário em ... (ou Sr. Delegado Regional Tributário em São Paulo), pelos motivos de fato e de direito a seguir expostos: I - DOS FATOS 1. A Impetrante, em 21-5-1995, foi intimada da lavratura de Auto de Infração e Imposição de Multa, pelo qual pretende a Fazenda Estadual a constituição de crédito tributário de ICMS incidente sobre operação de venda de mercadoria, sem emissão de Nota Fiscal, realizada em 5-10-1990. A autoridade coatora, ao emitir o competente ato de lançamento, aplicou a alíquota de 18% para a apuração do ICMS e a alíquota de 30% para a apuração da multa pelo não-recolhimento do imposto, conforme o disposto na Lei n. 7.896, de 23-3-1995. Ocorre, Excelência, que na data da ocorrência do fato imponível vigia a Lei n. 5.698/88, que fixava a alíquota do ICMS no percentual de 10%. Portanto, desde já, comprova-se a ilegalidade do presente lançamento tributário, uma vez que a lei aplicável ao presente caso é a lei vigente à época da ocorrência do fato imponível, conforme o disposto no art. 144 do Código Tributário Nacional. Resta claro, assim, o direito líquido e certo da Impetrante de não ser compelida ao recolhimento do crédito tributário de ICMS constituído por intermédio do Auto de Infração e Imposição de Multa, em face de sua flagrante ilegalidade. Estes os fatos. II - DO DIREITO 2. O artigo 150, inciso III, letra \"a\", do Texto Constitucional, ao dispor sobre o princípio da irretroatividade da lei tributária, assim disciplina: \"Art. 150. Sem prejuízo de outras garantias asseguradas ao contribuinte, é vedado à União, aos Estados, ao Distrito Federal e aos Municípios: III - cobrar tributos: a) em relação a fatos geradores ocorridos antes do início da vigência da lei que os houver instituído ou aumentado; \". O princípio da irretroatividade da lei tributária determina que a lei tributária que institui ou aumenta tributos somente poderá atingir fatos imponíveis ocorridos posteriormente ao início de sua vigência. Desde já se constata a nulidade do lançamento tributário ora questionado, tendo em vista a violação ao princípio da irretroatividade da lei tributária, já que a autoridade administrativa está pretendendo a cobrança do ICMS com a aplicação da alíquota disciplinada em lei posterior à ocorrência do fato imponível. Por outro lado, o artigo 144 do Código Tributário Nacional é expresso em determinar: \"Art. 144. O lançamento reporta-se à data da ocorrência do fato gerador da obrigação e rege-se pela lei então vigente, ainda que posteriormente modificada ou revogada\". A autoridade coatora, ao emitir o presente lançamento tributário, não atendeu ao disposto no art. 144 do Código Tributário Nacional, uma vez que aplicou lei posterior à ocorrência do fato imponível. Conforme acima exposto, a lei vigente à época do fato imponível era a Lei n. 5.698/88, que fixava a alíquota do ICMS no percentual de 10%, devendo, assim, a aludida alíquota ser aplicada à operação de venda de mercadoria realizada pela Autora em 5-10-1990, e não a alíquota de 18% utilizada pela Fazenda Estadual, uma vez que prevista em lei posterior à ocorrência do fato imponível. Nesse sentido as lições de LUCIANO AMARO, que assim ensina: \"O lançamento deve reportar-se à lei vigente na data da ocorrência do fato gerador, como determina o caput do preceito transcrito, o que equivale a dizer que ele deve reger-se pela lei vigente por ocasião do nascimento da obrigação tributária que dele seja objeto\" (Direito Tributário Brasileiro, Editora Saraiva, p. 338). 3. As únicas hipóteses de retroação da lei tributária estão disciplinadas no artigo 106 do Código Tributário Nacional: \"Art. 106. A lei aplica-se a ato ou fato pretérito: I - em qualquer caso, quando seja expressamente interpretativa, excluída a aplicação de penalidade à infração dos dispositivos interpretados; II - tratando-se de ato não definitivamente julgado: a) quando deixe de defini-lo como infração; b) quando deixe de tratá-lo como contrário a qualquer exigência de ação ou omissão, desde que não tenha sido fraudulento e não tenha implicado em falta de pagamento de tributo; c) quando lhe comine penalidade menos severa que a prevista na lei vigente ao tempo de sua prática\". A Lei n. 7.896/95, aplicada pela autoridade administrativa ao emitir o presente lançamento tributário, somente poderá prevalecer no tocante à multa aplicada, uma vez que disciplina penalidade menos severa que a lei vigente à época do fato imponível, porém jamais com relação à alíquota do imposto exigido. Resta demonstrada assim a total nulidade do presente lançamento tributário. III - DA CONCESSÃO DE MEDIDA LIMINAR 4. É flagrante a presença dos requisitos previstos no inciso II do artigo 7º da Lei n. 1.533/51. A relevância dos fundamentos repousa na total inconstitucionalidade e ilegalidade do lançamento consubstanciado no Auto de Infração e Imposição de Multa lavrado em 21 de maio de 1995, por total afronta ao princípio da irretroatividade da lei tributária, bem como por violação ao disposto no artigo 144 do Código Tributário Nacional, ao exigir o ICMS com base em alíquota instituída em lei posterior à ocorrência do fato imponível. Por outro lado, a ineficácia da segurança caso seja concedida ela somente ao final decorre do fato de que, sem a medida liminar, o crédito tributário será inscrito na dívida ativa e ajuizada Execução Fiscal, com penhora de bens, o que, de fato, acarretará prejuízos de toda ordem à Impetrante em face da demonstrada inexigibilidade do referido crédito tributário. IV - DO PEDIDO 5. Comprovado, à saciedade, o direito líquido e certo da Impetrante de não ser compelida ao recolhimento do crédito tributário consignado no Auto de Infração e Imposição de Multa lavrado em 21-5-1995, por sua flagrante ilegalidade. Ante o exposto, requer a Impetrante a concessão de medida liminar, a fim de sustar quaisquer atos a serem praticados por parte do Impetrado no sentido de inscrever o débito na dívida ativa e ajuizar Execução Fiscal tendente à exigibilidade do crédito de ICMS concernente à operação de circulação realizada em 5-10-1990. Processado o presente \"mandamus\", requisitadas as informações e ouvido o Ministério Público, requer a Impetrante a concessão da segurança em definitivo, a fim de ser cancelado o crédito tributário constituído pelo Auto de Infração e Imposição de Multa. Termos em que, dá-se a causa o valor de R$ (valor do crédito tributário)...., pede deferimento. Data Assinatura do Advogado', 'texto.png', NULL),
(16, 'CESSÃO DE DIREITOS SOBRE IMÓVEIS', 9, 0, 'A', '2025-09-29 15:27:19', '2026-08-20 20:02:47', 'Transferência, onerosa ou gratuita, de direitos aquisitivos/posse oriundos de promessa de compra e venda, fração ideal etc. Em regra exige anuência do promitente vendedor/incorporador; forma pública quando o valor superar 30 salários-mínimos (CC, art. 108). Pode incidir ITBI/ITCMD, conforme o caso e a legislação local. Oponível a terceiros após registro no Cartório de Registro de Imóveis.', '<p>Por este instrumento particular de cess&atilde;o de direitos sobre im&oacute;veis, de um lado <strong>[requerido_nome]</strong> , CPF: <strong>[requerido_cpf_cnpj]</strong>, RG: [requerido_rg_ie] <strong>[requerido_nacionalidade]</strong> , <strong>[requerido_estado_civil]</strong> , <strong>[requerido_profissao]</strong> domiciliado(a) &agrave; <strong>[requerido_logradouro]</strong> <strong>[requerido_endereco]</strong>, <strong>[requerido_nr]</strong> cep <strong>[requerido_cep]</strong> de outro lado <strong>[requerente_nome] </strong>CPF: <strong>[requerente_cpf_cnpj]</strong> , RG: <strong>[requerente_rg_ie]</strong> , <strong>[requerente_nacionalidade]</strong> , <strong>[requerente_estado_civil]</strong> , <strong>[requerente_profissao]</strong>, domiciliado(a) &agrave; <strong>[requerente_logradouro]</strong> <strong>[requerente_endereco]</strong>, <strong>[requerente_nr]</strong> cep <strong>[requerente_cep]</strong> ,&nbsp; de ora em diante chamados simplesmente de CEDENTE, e, CESSION&Aacute;RIO, t&ecirc;m, entre si, como justo e contratado o que se segue e que mutuamente acordam:</p>\n<p>1&ordm; - Por for&ccedil;a de contrato de promessa de compra e venda, o CEDENTE tornou-se titular dos direitos aquisitivos do im&oacute;vel<strong> [campo1]</strong> .</p>\n<p>2&ordm; - Diz o CEDENTE que o im&oacute;vel descrito e caracterizado na cl&aacute;usula anterior se acha livre e desembara&ccedil;ado de todos e quaisquer &ocirc;nus judiciais e extrajudiciais, foro, pens&atilde;o e hipoteca de qualquer natureza, bem como quite de impostos e taxas.</p>\n<p>3&ordm; - Achando-se, como se acha igualmente pago o pre&ccedil;o pactuado no mencionado compromisso de compra e venda, o CEDENTE, por este instrumento particular e na melhor forma de direito, promete e se obriga a ceder e transferir ao CESSION&Aacute;RIO todos os direitos decorrentes daquele contrato, dentro das cl&aacute;usulas e condi&ccedil;&otilde;es deste instrumento de cess&atilde;o de direitos.&nbsp; Achando-se, ainda, o pre&ccedil;o pactuado no mencionado compromisso de compra e venda com <strong>[campo2]</strong>&nbsp;parcelas ou presta&ccedil;&otilde;es a pagar cada uma no valor de R$&nbsp;<strong>[campo3] </strong>(<strong>[extenso3]</strong>), venc&iacute;veis a partir de&nbsp;<span class=\"hljs-string\"><strong>[campo4] </strong></span>, o CEDENTE, por este instrumento particular e na melhor forma de direito, promete e se obriga a ceder e transferir ao CESSION&Aacute;RIO todos os direitos decorrentes daquele contrato, dentro das cl&aacute;usulas e condi&ccedil;&otilde;es deste instrumento de cess&atilde;o de direitos.</p>\n<p>4&ordm; - O pre&ccedil;o certo e ajustado para a cess&atilde;o &eacute; de R$ <strong>[campo5] </strong>(<strong>[extenso5]</strong>), dos quais a import&acirc;ncia de R$ <strong>[campo6] </strong>(<strong>[extenso6]</strong>) &eacute; recebida neste ato, pelo CEDENTE, <strong>[extenso7]</strong>, emitido pelo CESSION&Aacute;RIO, pelo que o CEDENTE d&aacute; a mais geral, rasa e irrevog&aacute;vel quita&ccedil;&atilde;o para nada mais exigir em rela&ccedil;&atilde;o a ele, e a import&acirc;ncia de R$ <strong>[campo9]</strong> (<strong>[extenso9]</strong>) ser&aacute; paga em <strong>[campo10]</strong> presta&ccedil;&otilde;es mensais, sem juros, iguais e sucessivas, vencendo-se a primeira presta&ccedil;&atilde;o no valor de R$ <strong>[campo11]</strong> (<strong>[extenso11]</strong>)&nbsp;em&nbsp;<strong>[campo12]</strong>, e as demais em igual dia dos meses subseq&uuml;entes.&nbsp;</p>\n<p>5&ordm; - O pagamento das presta&ccedil;&otilde;es {ou parcelas} aqui pactuadas ser&aacute; feito na resid&ecirc;ncia do CEDENTE, ou em local onde este indicar, com uma toler&acirc;ncia de at&eacute; (<strong>[campo13]</strong>) dias ap&oacute;s o respectivo vencimento, e permanecer&atilde;o vinculadas a este instrumento.</p>\n<p>6&ordm; - No caso de impontualidade no pagamento de qualquer das presta&ccedil;&otilde;es, pagar&aacute; o CESSION&Aacute;RIO os juros de mora de <strong>[campo14]</strong>% (por cento) ao m&ecirc;s, enquanto perdurar o atraso.</p>\n<p>7&ordm; - Se o atraso resultar em falta de pagamento de 03 (tr&ecirc;s) presta&ccedil;&otilde;es consecutivas, ficar&aacute; de pleno direito vencida toda a d&iacute;vida independentemente de aviso ou notifica&ccedil;&atilde;o judicial ou extrajudicial, sujeitando-se o CESSION&Aacute;RIO &agrave; cobran&ccedil;a executiva da mesma, acrescida da multa de <strong>[campo15]</strong>%&nbsp; do valor total do d&eacute;bito, sem preju&iacute;zo dos juros morat&oacute;rios previstos na cl&aacute;usula anterior.&nbsp;</p>\n<p>8&ordm; -&nbsp;O CESSION&Aacute;RIO &eacute;, neste ato, imitido na posse do im&oacute;vel, ficando a seu cargo, a partir desta data, o pagamento de todos os tributos, taxas e tarifas que incidam ou venham a incidir sobre o referido im&oacute;vel.</p>\n<p>9&ordm; - Correr&atilde;o por conta do CESSION&Aacute;RIO todas as despesas que forem necess&aacute;rias para a efetiva&ccedil;&atilde;o da cess&atilde;o ora prometida, inclusive certid&otilde;es negativas e todos e quaisquer tributos que onerem ou venham a onerar a presente transa&ccedil;&atilde;o.</p>\n<p>10&ordm; - O presente instrumento, em todos os seus termos, &eacute; feito em car&aacute;ter irrevog&aacute;vel, obrigando a herdeiros e sucessores das partes contratantes.</p>\n<p>11&ordm; - A escritura definitiva ser&aacute; realizada t&atilde;o logo esteja paga a &uacute;ltima presta&ccedil;&atilde;o, e se o CESSION&Aacute;RIO foi obrigado a recorrer aos meios judiciais para obter a sua adjudica&ccedil;&atilde;o compuls&oacute;ria, pagar&aacute; ao CEDENTE a multa de&nbsp;<strong>[campo15]</strong>%, al&eacute;m dos honor&aacute;rios de advogado(s) do CESSION&Aacute;RIO.</p>\n<p>12&ordm; - As partes elegem o Foro desta cidade para dirimir as quest&otilde;es oriundas deste contrato, com ren&uacute;ncia de qualquer outro, por mais privilegiado que seja. E por estarem as partes, Cedente e Cession&aacute;rio, em pleno acordo, em tudo quanto se encontra disposto neste instrumento particular, assinam-no na presen&ccedil;a das duas testemunhas abaixo em <strong>[campo16]</strong> vias de igual teor e forma, destinando-se uma via para cada uma das partes contratadas neste instrumento.</p>', 'texto.png', NULL),
(17, 'CESSÃO DE DIREITOS PATRIMONIAIS', 1, 0, 'A', '2025-09-29 22:11:32', '2025-09-29 22:40:16', 'Direito das Obrigações: Esta é a sua área central. A cessão é uma forma de transmissão de obrigações. O Código Civil brasileiro regula especificamente a Cessão de Crédito (artigos 286 a 298), que é o modelo clássico para a transferência de direitos patrimoniais de natureza creditícia.\r\nDireito Contratual: A cessão de direitos é formalizada por meio de um contrato (negócio jurídico), que estabelece os termos da transferência entre o cedente (quem cede o direito) .', 'CESSÃO DE DIREITOS PATRIMONIAIS Pelo presente instrumento particular, de um lado ............ (denominação) localizada à rua .........................., n.º..........,na cidade de........................, Estado de ..................., inscrita no CGC sob o n.º.............................e Inscrição Estadual n.º.........................., neste ato representada por seu Diretor....................(titulação),................................(nome completo e por extenso do diretor), de ora em diante designada simplesmente EDITORA, e, de outro lado ................................, (nome completo e por extenso do autor), nacionalidade ................................., estado civil..........., profissão............., CIC n.º......., Cédula de Identidade RG n.º............, residente e domiciliado à Rua.................., n.º......, na cidade de............, Estado de................., de ora em diante chamado simplesmente de AUTOR, têm, entre si, como justo e contratado, na melhor forma de direito, o seguinte: 1º - O AUTOR cede e transfere, para ser exercido em língua portuguesa, à EDITORA, os direitos patrimoniais de autor, discriminados na cláusula 2ª deste instrumento, da obra literária de sua autoria, intitulada.................................................(nome da obra), na forma, extensão e aplicação da legislação em vigor e da que vier a vigorar no futuro.2º - Com a presente alienação, passam à EDITORA, por definitiva transferência, todos os direitos e faculdades que no seu conjunto constituem o direito autoral do cedente, sobre a obra cedida, em todos os seus aspectos, manifestações e aplicações diretas ou indiretas, processos de reprodução e divulgação ou extensões e ampliações, com todas as faculdades de exploração comercial e industrial que forem necessárias para o exercício dos direitos cedidos, a exclusivo arbítrio da EDITORA, efetuando onde quer que se lhe afigure útil ou conveniente, os registros e depósitos necessários para irrestrito reconhecimento de seu direito de propriedade, consoante o art. 673 do Código Civil.3º - Fica a EDITORA, desde já, constituída procuradora do AUTOR, cedente em causa própria, com poderes irrevogáveis, segundo o disposto no Código Civil, art. 1.317, para os fins de defesa dos direitos da obra cedida contra quem quer que pratique atentados defesos em lei.4º - O AUTOR ficará exclusiva e pessoalmente responsável pela originalidade da obra cedida, exonerada a EDITORA de todas e quaisquer responsabilidades correspondentes e obrigando-se o AUTOR a indenizá-la por perdas e danos que vier a sofrer em caso de contestação (evicção, art. 1.107 do Código Civil).5º - A EDITORA obriga-se a editar, divulgar, publicar e comercializar a obra objeto desse contrato, ficando a eu exclusivo critério a tiragem de cada edição, o número de edições, a fixação da época de lançamento no mercado, a determinação da forma e detalhes de apresentação do produto e o preço de venda ao público de cada exemplar.6º - A presente alienação é feita a título oneroso e por preço certo, representado pela importância única de....................................................(por extenso) a ser paga à vista.Parágrafo único - O AUTOR declara, sob sua responsabilidade, não existir nenhuma proibição tácita, vinculada à divulgação da obra de sua autoria, objeto do presente contrato.7º - Fica eleito o Foro da cidade de.......................................para dirimir quaisquer dúvidas oriundas do presente contrato, com renúncia expressa de qualquer outro, por mais privilegiado que seja.8º - Em caso de qualquer pendência fundada neste contrato, a parte que for julgada vencida ficará com os encargos da demanda, inclusive os honorários do advogado da parte julgada vencedora.E por estarem as partes em pleno acordo com o disposto neste instrumento particular, assinam-no na presença das duas testemunhas abaixo, em duas vias de igual teor e forma, destinando-se uma via para cada uma das partes contratadas neste instrumento...........................,..................de..................de .............................................................................................................................................................Testemunhas:1ª - .........................2ª - .........................', 'texto.png', NULL),
(18, 'CESSÃO DE QUOTAS DE SOCIEDADE À PRAZO', 7, 0, 'A', '2025-09-29 22:48:04', '2025-09-29 22:48:46', 'Cessão de quotas de sociedade a prazo = contrato pelo qual um sócio transfere suas quotas (total ou parcial) a outra pessoa, com pagamento parcelado.', 'CESSÃO DE QUOTAS DE SOCIEDADE À PRAZO Pelo presente instrumento particular de cessão e transferência de quotas sociais, de um lado ............................... (nome completo do cedente), residente e domiciliado à .................................................... n.º ......., (endereço completo do cedente), .............................. RG n.º ................................... (número da identidade do cedente), CIC n.º ................................. (número do CPF do cedente), sócio quotista da firma ................. (denominação da firma ou razão social em que o cedente é sócio), com sede à ............................................................... (endereço completo de firma ou empresa, cujas quotas sociais estão sendo negociadas), na cidade de ...................., Estado de .................., (cidade e Estado em que se situa a sede da empresa), CGC n.º .................... (número do CGC da empresa), com contrato social arquivado na Junta Comercial do Estado de ................................, sob número ..................... (dados do contrato inicial da empresa) e alterações contratuais sob números ............, .........., ........... (citar todas as alterações sociais da empresa, arquivadas na Junta Comercial do respectivo Estado), de ora em diante chamado simplesmente de CEDENTE e, de outro lado, ............................................ (nome completo de quem está adquirindo as quotas), de nacionalidade ..........................., de profissão .............................., estado civil ....................., residente e domiciliado à ............................................. n.º ........ (endereço completo de quem está adquirindo as quotas), na cidade de ..........................., Estado de .................................., RG n.º ..................... (número da identidade de quem está adquirindo as quotas), CIC n.º ................................................... (número do CPF de quem está adquirindo as quotas), (se a aquisição das quotas está sendo realizada por uma outra empresa, a identificação do cessionário será a da empresa adquirente das quotas, naturalmente representada por um dos sócios ou gerentes ou elemento legalmente autorizado para a aquisição), de ora em diante chamado simplesmente de CESSIONÁRIO, têm, entre si, como justo e contratado, o que se segue: 1º - O CEDENTE é detentor, por todos os títulos de direito, de .....(quantidade de quotas sociais) quotas sociais, no valor de R$........................ (valor de cada quota, segundo o contrato social ou suas alterações), totalizando R$ ............ (valor total das quotas sociais), consoante contrato social e alterações citadas especificamente no intróito deste instrumento contratual.2º - As respectivas quotas do CEDENTE estão (ou não estão) inteiramente integralizadas (se não estiverem inteiramente integralizadas, citar a quantidade e os valores das que deverão sê-las).3º - (Se houver, no contrato social, direito de preferência pela aquisição de quotas pelos outros sócios). Ofertou o CEDENTE as quotas sociais de que era titular aos demais sócios da sociedade, consoante o disposto na cláusula ............ (citar o número da cláusula do contrato social da empresa), sem que os mesmos se interessassem em exercer o seu direito de preferência (ou: abrindo os mesmos mão de seu direito de preferência), conforme correspondência que se anexa a este instrumento, ficando o CEDENTE livre para negociá-las com terceiros.4º - O CEDENTE, por este instrumento, cede ao CESSIONÁRIO as quotas sociais de que é titular, e já integralizadas, pelo valor de R$................................................................ (valor total da transação das quotas), assim como todos os seus direitos e obrigações contratuais.5º - O CESSIONÁRIO pagará o valor referido na cláusula anterior, da seguinte forma: ............................................................ (descrever a forma do pagamento, o valor, se for dado, neste ato, e as parcelas futuras que poderão ser representadas por Notas Promissórias e esclarecer se nas prestações subsequentes serão contados juros e correção monetária).6º - O CEDENTE obriga-se à transferência oficial das quotas da sociedade, transacionadas por este instrumento, até o dia ........ de ............................ de ......... (dia, mês e ano), ao CESSIONÁRIO, através de alteração contratual que fará elaborar por advogado e que será por ele assinada, juntamente com o outro (ou os demais sócios, se houver mais de um sócio além do CEDENTE), integrando o CESSIONÁRIO no domínio das quotas respectivas e seus direitos e obrigações conseqüentes.7º - O CESSIONÁRIO obriga-se ao arquivamento da alteração contratual, pela cessão e transferência de quotas, até o prazo de 30 (trinta) dias, contados da data da sua assinatura, sob pena de, se não o fazendo, investir o CEDENTE da autorização de fazê-lo para valer a cessão e transferência diante de terceiros.8º - Declara-se o CESSIONÁRIO inteiramente ciente do estado econômico e financeiro da empresa cujas quotas estão, parcialmente, sendo transferidas e cedidas por este ato, nada podendo alegar, sobre estas situações, para retratar-se ou reverter esta transação.9º - Este contrato é celebrado sob a condição expressa de sua irrevogabilidade e irretratabilidade, ressalvando o eventual inadimplemento do CESSIONÁRIO, renunciando os contratantes, expressamente, à faculdade de arrependimento concedida pelo art. 1.095 do Código Civil e quaisquer outros do Código Comercial.10º - Para dirimir quaisquer questões que direta ou indiretamente decorrem deste contrato, as partes elegem o Foro desta Comarca, com renúncia expressa de qualquer outro por mais privilegiado que seja.11º - Para todos os fins e efeitos de direito, os contratantes declaram aceitar o presente contrato nos expressos termos em que foi lavrado, obrigando-se a si, seus herdeiros e sucessores a bem e fielmente cumpri-lo.E por estarem assim ajustadas e em perfeito acordo em tudo quanto neste instrumento particular foi lavrado, obrigam-se as partes a cumprir o presente contrato, assinando-o na presença das duas testemunhas abaixo, em ......... (número de vias) vias, de igual teor........................, ......... de ......................... de ..............................................................(assinatura do CEDENTE) ....................................................(assinatura do CESSIONÁRIO) Testemunhas: 1ª - .............................................2ª - .............................................______________________ Observação: O valor da transação, neste contrato, poderá ser maior que o valor das quotas sociais ou menor que elas, quando, então, haverá o ágio ou deságio que beneficia ou leva prejuízo ao cedente como pessoa física.O valor deste contrato, na contabilidade, não aparecerá, salvo na contabilidade do cessionário, se este for pessoa jurídica.', 'texto.png', NULL),
(19, 'CESSÃO DE QUOTAS DE SOCIEDADE À VISTA', 7, 0, 'A', '2025-09-29 22:55:38', '2025-09-29 22:56:31', 'Transferência, de imediato, das quotas de uma Ltda (ou sociedade simples) do cedente ao cessionário, com pagamento integral na assinatura. Área do direito: Empresarial/Societário (com regramento civil/contratual).', 'CESSÃO DE QUOTAS DE SOCIEDADE À VISTA Pelo presente instrumento particular de cessão e transferência de quotas sociais, de um lado ................................................................... (nome completo do cedente), residente e domiciliado à ............................................ n.º ........, (endereço completo do cedente), ..............................., RG n.º ............................ (número de identidade do cedente), CIC n.º ..............................., (número do CPF do cedente), sócio quotista da firma .............................................. (denominação da firma ou razão social em que o cedente é sócio), com sede à ................................., (endereço completo de firma ou empresa, cujas quotas sociais estão sendo negociadas), na cidade de ....................., Estado de ...................., (cidade e Estado em que se situa a sede da empresa), CGC n.º ................, (número do CGC da empresa), com contrato social arquivado na Junta Comercial do Estado de ......................................................, sob número ........................ (dados do contrato inicial da empresa) e alterações contratuais sob números ........................, ...................., (citar todas as alterações sociais da empresa, arquivadas na Junta Comercial do respectivo Estado) de ora em diante chamado simplesmente de CEDENTE e, do outro lado, ............................................, (nome completo de quem está adquirindo as quotas), de nacionalidade ......................., de profissão ............................., estado civil ................................, residente e domiciliado à .......................................... n.º ........, (endereço completo de quem está adquirindo as quotas), na cidade de ......................., Estado de ..........................................., RG n.º ...................... (número da identidade de quem está adquirindo as quotas), CIC n.º ............................................., (número do CPF de quem está adquirindo as quotas) (se a aquisição das quotas está sendo realizada por uma outra empresa, a identificação do cessionário será a da empresa adquirente das quotas, naturalmente representada por um dos sócios ou gerentes ou elemento legalmente autorizado, chamado simplesmente de CESSIONÁRIO, têm, entre si, como justo e contratado, o que se segue: 1º - O CEDENTE é detentor, por todos os títulos de direito, de ...................... (quantidade de quotas sociais) quotas sociais, no valor de R$........................ (valor de cada quota, segundo o contratado social ou suas alterações), totalizando R$ a ............................................. (valor total das quotas sociais), consoante contrato social e alterações citadas especificamente no intróito deste instrumento contratual.2º - As respectivas quotas do CEDENTE estão (ou não estão) inteiramente integralizadas (se não estiverem inteiramente integralizadas, citar a quantidade e os valores das que deverão sê-las).3º - (Se houver, no contrato social, direito de preferência pela aquisição de quotas pelos outros sócios). Ofertou CEDENTE as quotas sociais de que era titular aos demais sócios da sociedade, consoante o disposto na cláusula ............ (citar o número da cláusula do contrato social da empresa), sem que os mesmos se interessassem em exercer o seu direito de preferência (ou: abrindo os mesmos mão de seu direito de preferência), conforme correspondência que se anexa a este instrumento, ficando o CEDENTE livre para negociá-las com terceiros.4º - O CEDENTE, por este instrumento, cede ao CESSIONÁRIO as quotas sociais de que é titular, e já integralizadas, pelo valor de R$............................ (valor total da transação das quotas), assim como todos os seus direitos e obrigações contratuais.5º - O CESSIONÁRIO paga, neste ato, através do cheque número .............................. (número do cheque emitido pelo cessionário), emitido contra o Banco .................................. (banco contra o qual o cheque foi emitido), o valor de R$.............................................. (valor total da transação, referido na cláusula 4ª, acima), dando o CEDENTE, por este ato, total e plena quitação de seus haveres, nada mais tendo a reclamar do CESSIONÁRIO a nenhum título, por esta transação.6º - O CEDENTE obriga-se à transferência oficial das quotas da sociedade, transacionadas por este instrumento, até o dia ........ de ............................ de 19........ (dia, mês e ano), ao CESSIONÁRIO, através de alteração contratual que fará elaborar por advogado e que será por ele assinada, juntamente com o outro (ou os demais sócios, se houver mais de um sócio além do CEDENTE), integrando o CESSIONÁRIO no domínio das quotas respectivas e seus direitos e obrigações conseqüentes.7º - O CESSIONÁRIO obriga-se ao arquivamento da alteração contratual, pela cessão e transferência de quotas, até o prazo de 30 (trinta) dias, contados da data da sua assinatura, sob pena de, se não o fazendo, investir o CEDENTE da autorização de fazê-lo, para valer a cessão e transferência diante de terceiros.8º - Declara-se o CESSIONÁRIO inteiramente ciente do estado econômico e financeiro da empresa cujas quotas estão, parcialmente, sendo transferidas e cedidas por este ato, nada podendo alegar, sobre estas situações, para retratar-se ou reverter esta transação.9º - Este ao é celebrado sob a condição expressa de sua irrevogabilidade e irretratabilidade.10º - Para dirimir quaisquer questões que direta ou indiretamente decorrerem deste contrato, as partes elegem o Foro desta Comarca, com renúncia expressa de qualquer outro por mais privilegiado que seja.11º - Para todos os fins e efeitos de direito, os contratantes declaram aceitar o presente contrato nos expressos termos em que foi lavrado, obrigando-se a si, seus herdeiros e sucessores a bem e fielmente cumpri-lo.E por estarem assim ajustados e em perfeito acordo em tudo quanto neste instrumento particular foi lavrado, obrigam-se as partes a cumprir o presente contrato, assinando-o na presença das duas testemunhas abaixo, em .................... (número de vias) vias, de igual teor..............................., ....... de ..................... de ............................................................(assinatura do CEDENTE) ....................................................(assinatura do CESSIONÁRIO) Testemunhas: 1ª - .........................................2ª - .........................................________________________ Observação: O valor da transação, neste contrato, poderá ser maior que o valor das quotas sociais ou menor que elas, quando, então, haverá o ágio ou deságio que beneficia ou leva prejuízo ao cedente como pessoa física.O valor deste contrato, na contabilidade, não aparecerá, salvo na contabilidade do cessionário, se este for pessoa jurídica.', 'texto.png', NULL);
INSERT INTO `textos` (`id`, `nome`, `area_id`, `texto_id`, `status`, `created_at`, `updated_at`, `obs`, `texto`, `avatar`, `nmtexto`) VALUES
(20, 'PETICAO INICIAL PASEP', 4, 0, 'A', '2025-10-01 02:12:51', '2025-10-01 02:23:01', 'AÇÃO DE COBRANÇA/INDENIZAÇÃO\r\n(REPARAÇÃO DE DIFERENÇAS DE RENDIMENTOS DO PASEP)\r\ncom pedido de tutela de urgência [se aplicável]', 'EXMO(A). SR(a). DR(a). JUIZ(a) DE DIREITO DA ___ VARA CÍVEL DA COMARCA DE SÃO PAULO DO ESTADO DE SÃO PAULO Requerente, Brasileiro, Aposentado, portador (a) do documento de identidade nº 14.709.984-5, expedida por SSP/SP, inscrito no CPF sob o nº 000.000.000-00, e-mail email@email.com, residente e domiciliado (a) na Rua Endereço, 000, Bairro Vila Bairro, Cidade Cidade, Estado AA, CEP: 000000-000, vem a presença de Vossa Excelência, por intermédio do (a) advogado (a) subscrito (a), cuja procuração segue anexa, propor a presente AÇÃO ORDINÁRIA DE COBRANÇA DE VALORES DE PASEP C/C PEDIDO DE DANOS MATERIAIS em face de, BANCO DO BRASIL S.A, sociedade de econômia mista, inscrito no CNPJ sob o n.º 00.000.000/0001-91, representado para este fim por seu presidente, a ser citado na pessoa de um de seus representantes legais, com endereço situado no SBS Quadra 01 Lote 32 Bloco C - Ed. Sede III, 24º andar, Setor Bancário Sul, Brasília, DF, Brasil, CEP 70073-901, Telefone (061) 31020-000, e-mail presidencia@bb.com.br; I - DA ASSISTÊNCIA JUDICIÁRIA GRATUITA O Autor é pessoa pobre na acepção do termo e não possui condições financeiras para arcar com as custas processuais e honorários advocatícios sem prejuízo do próprio sustento, razão pela qual desde já requer o benefício da Gratuidade de Justiça, assegurados pela Lei nº. 1060/50 e consoante o art. 98, caput, do CPC: Art. 98. A pessoa natural ou jurídica, brasileira ou estrangeira, com insuficiência de recursos para pagar as custas, as despesas processuais e os honorários advocatícios tem direito à gratuidade da justiça, na forma da lei Para tal benefício, junta declaração de hipossuficiência, o qual demonstra a inviabilidade de pagamento das custas judiciais sem comprometer sua subsistência, conforme clara redação do CPC: Art. 99. O pedido de gratuidade da justiça pode ser formulado na petição inicial, na contestação, na petição para ingresso de terceiro no processo ou em recurso. (...) § 3º Presume-se verdadeira a alegação de insuficiência deduzida exclusivamente por pessoa natural. Assim, por simples petição, sem outras provas exigíveis por lei, faz jus a parte Autora, ao benefício da gratuidade de justiça, com fulcro no artigo 5º, LXXIV da Constituição Federal e pelo artigo 98 do CPC, requer seja deferida a gratuidade de justiça a parte Autora. II. PRIORIDADE NA TRAMITAÇÃO DO PROCESSO Diante do exposto, requer a Vossa Excelência que seja concedida prioridade na tramitação do presente processo, nos termos do art. 70 do Estatuto do Idoso, em razão da idade avançada do autor, que conta atualmente com idade 64 anos. A demora na tramitação deste processo poderá acarretar prejuízos irreparáveis ao autor, considerando suas condições de saúde e a necessidade de uma solução célere para a presente demanda. III. LEGITIMIDADE PASSIVA - BANCO DO BRASIL A competência para a administração do PASEP foi transferida para o Banco do Brasil após a promulgação da Constituição Federal de 1988. Antes dessa mudança, os fundos do PASEP não eram individualizados para cada servidor. Em vez disso, os recursos eram agrupados em um fundo comum, sem contas específicas para cada servidor. No entanto, com a promulgação da CF/88, o fundo do PASEP foi transferido para o Fundo de Amparo ao Trabalhador (FAT), marcando um novo capítulo para os servidores que contribuíram para o PASEP antes de 1988.  Considerando tratar-se de valores devidos pela má gestão do Banco Réu, é inquestionável a sua legitimidade, conforme pacificado pelo STJ, no Tema Repetitivo 1150, com a seguinte tese: \"(...) 6. No entanto, no caso dos autos a demanda não versa sobre índices equivocados de responsabilidade do Conselho Gestor do Fundo, mas sobre responsabilidade decorrente da má gestão do banco, em razão de saques indevidos ou de não aplicação dos índices de juros e de correção 1monetária na conta do Pasep. Conclui-se que a legitimidade passiva é do Banco do Brasil S.A. Nesse sentido: AgInt no REsp 1.898.214/SE, Rel. Ministro Francisco Falcão, Segunda Turma, DJe de 29.4.2021; AgInt no REsp 1.867.341/DF, Rel. Ministra Assusete Magalhães, Segunda Turma, DJe de 7.10.2021; REsp 1.895.114/DF, Rel. Ministro Herman Benjamin, Segunda Turma, DJe de 14.4.2021; AgInt no REsp 1.954.954/CE, Rel. Ministra Regina Helena Costa, Primeira Turma, DJe de 25.3.2022; e AgInt no REsp 1.922.275/CE, Rel. Ministro Gurgel de Faria, Primeira Turma, DJe de 29.6.2021. (STJ,, REsp n. 1.895.936/TO, relator Ministro Herman Benjamin, Primeira Seção, julgado em 13/9/2023, DJe de 21/9/2023). Dessa forma, como a ação trata da má-gestão dos valores da conta PASEP da De Cujus, o Banco do Brasil é parte legítima para figurar no polo passivo desta ação. A competência para julgar as ações de revisão do PASEP contra o Banco do Brasil foi definida pelo Superior Tribunal de Justiça (STJ). De acordo com decisões recentes, a competência é estadual, o Banco do Brasil é considerado uma empresa pública de economia mista. Isso significa que ele possui características tanto de uma empresa estatal quanto de uma empresa privada, . Segundo entendimento dos tribunais brasileiros, a relação entre um correntista titular de conta do PASEP e o Banco do Brasil pode ser enquadrada como relação de consumo, o Código de Defesa do Consumidor (CDC) define consumidor como toda pessoa física ou jurídica que adquire ou utiliza produto ou serviço como destinatário final. No caso de serviços bancários, como a manutenção de conta corrente, o correntista é considerado consumidor, pois utiliza os serviços bancários oferecidos pelo Banco do Brasil como destinatário final. IV. DOS FATOS O Autor devidamente qualificado nos autos, após tomar ciência sobre a possibilidade de análise e revisão do saldo de sua conta Pasep, foi possível perceber, com auxílio da ciência da contabilidade, que a correção dos valores depositados na sua conta PASEP, foram irregulares, havendo ausência de correção/créditos em diversos períodos temporais. Desta forma, conclui-se que a instituição financeira Ré não promoveu a devida administração e correção do PASEP ao longo do período functional do autor, resultando em perda material, também conhecida como dano material ou prejuízo material, é um conceito jurídico que se refere a qualquer diminuição patrimonial sofrida por uma pessoa em decorrência de um ato ilícito praticado por outra. Em outras palavras, é a perda financeira ou a redução do patrimônio de alguém causada por um dano. Os extratos juntados aos autos demonstram essa condição. Não poderia o Requerente ter um saldo e valores diminutos, é inegável que o Brasil passou por um período de hiperinflação. Essa fase turbulenta da economia brasileira marcou profundamente a vida da população e deixou sequelas duradouras. Para a constatação e aclaramento dos dados aqui citados foi gerado uma planilha com lançamentos provinientes das microfichas e extrato da conta do Pasep do autor, documentos em anexo, requerido junto ao réu Banco do Brasil, documento em anexo. Portanto, fica evidenciado que os valores depositados relativos aos programas PASEP, foram mal geridos pela instituição financeira Ré, que era responsável pela recomposição do saldo. Assim, pretende com a presente ação garantir seu direito à correção dos valores do PASEP, de acordo com índices legais, bem como, restituição das diferenças dos últimos anos e obviamente o recebimento. V. DO DIREITO A - PASEP - Programa de Formação do Patrimônio do Servidor Público A Lei Complementar Federal nº. 8/1970 criou o Programa de Formação do Patrimônio do Servidor Público - PASEP, abrangendo os Servidores Públicos de todos os entes federativos, como se nota no artigo 4º da referida LC: Art. 4º - As contribuições recebidas pelo Banco do Brasil serão distribuídas entre todos os servidores em atividade, civis e militares, da União, dos Estados, Municípios, Distrito Federal e Territórios, bem como das suas entidades da Administração Indireta e fundações, observados os seguintes critérios: (...)Parágrafo único - A distribuição de que trata este artigo somente beneficiará os titulares, nas entidades mencionadas nesta Lei Complementar, de cargo ou função de provimento efetivo ou que possam adquirir estabilidade, ou de emprego de natureza não eventual, regido pela legislação trabalhista. Com o advento da Constituição Federal de 1988, a destinação dos recursos do PIS - PASEP foi modificada, passando a ter outros fins, quais sejam, o financiamento do programa de seguro-desemprego e o abono salarial. Nesse sentido: Art. 239. A arrecadação decorrente das contribuições para o Programa de Integração Social, criado pela Lei Complementar nº 7, de 7 de setembro de 1970, e para o Programa de Formação do Patrimônio do Servidor Público, criado pela Lei Complementar nº 8, de 3 de dezembro de 1970, passa, a partir da promulgação desta Constituição, a financiar, nos termos que a lei dispuser, o programa do seguro-desemprego e o abono de que trata o § 3º deste artigo. A Constituição Federal garantiu o patrimônio acumulado do Programa de Integração Social e do Programa de Formação do Patrimônio do Servidor Público, inclusive mantendo-se os critérios de saque nas situações previstas nas leis específicas, com exceção da retirada por motivo de casamento. Porém, parece que o Banco Réu em algum momento suprimiu ou não creditou valores e correções, que mesmo com todo o período funcional, anos de trabalho, não recebeu o que era seu de direito referente a seu periodo laboral, conforme microfichas , documentos em anexo. O Código Civil prevê que: Art. 186. Aquele que, por ação ou omissão voluntária, negligência ou imprudência, violar direito e causar dano a outrem, ainda que exclusivamente moral, comete ato ilícito. Art. 927. Aquele que, por ato ilícito (arts. 186 e 187), causar dano a outrem, fica obrigado a repará-lo. Destarte, deve a Ré reparar os danos causados ao Autor, teve valores relativos ao PASEP, não creditados, ou extraídos indevidamente, além da ausência de rendimentos estabelecidos pelo Conselho Diretor do programa, o que gerou sem dúvida prejuízo material. Experimenta o dano, como prova o saldo apresentado pelo Banco do Brasil em comparativo ao cálculo elaborado, levando em consideração os encargos que são devidos por Lei. Os Tribunais Pátrios têm decidido em situações análogas: APELAÇÃO CÍVEL. AÇÃO ORDINÁRIA QUE VISA CONTESTAR A GESTÃO DOS VALORES DEPOSITADOS NA CONTA VINCULADA AO PASEP. CORREÇÃO MONETÁRIA DO SALDO DA CONTA DO PIS /PASEP. RECOMPOSIÇÃO E RESTITUIÇÃO DE VALORES QUE ALEGA DESFALCADOS DA CONTA DO BENEFICIÁRIO. PRELIMINAR DE LEGITIMIDADE DO BANCO DO BRASIL. ACOLHIDA. SENTENÇA ANULADA. RECURSO PROVIDO. 1. Consoante assentado pelo Superior Tribunal de Justiça no Tema 1.150, julgado pela sistemática dos recursos repetitivos, o Banco do Brasil é parte legítima para figurar no polo passivo de ações judiciais que discutem a gestão de valores depositados em contas do PASEP. 2. Diante da tese fixada sob o rito dos recursos especiais repetitivos, de rigor declarar a nulidade da sentença que extinguiu a ação, sem resolução do mérito, sob o fundamento de ilegitimidade passiva do Banco do Brasil, bem como determinar o retorno dos autos à origem para o seu regular processamento. 3. Preliminar de legitimidade acolhida. Sentença desconstituída. Recurso provido. (TJ-AC - Apelação Cível: 0710298-08.2020.8.01.0001 Rio Branco, Relator: Desª. Waldirene Cordeiro, Data de Julgamento: 26/11/2023, Segunda Câmara Cível, Data de Publicação: 26/11/2023); AGRAVO DE INSTRUMENTO – AÇÃO DE COBRANÇA DE PASEP – PRELIMINARES DE ILEGITIMIDADE PASSIVA, INCOMPETÊNCIA DA JUSTIÇA ESTADUAL E PRESCRIÇÃO – AFASTADAS – TESE FIRMADA NO TEMA 1150 DO STJ – INVERSÃO ÔNUS DA PROVA – POSSIBILIDADE – APLICAÇÃO DO ARTIGO 373, § 1º, CPC – MATÉRIA PRECLUSA – DECISÃO MANTIDA – RECURSO CONHECIDO E DESPROVIDO. No julgamento do Tema 1150 do STJ, firmaram-se as as seguintes teses: \"i) o Banco do Brasil possui legitimidade passiva ad causam para figurar no polo passivo de demanda na qual se discute eventual falha na prestação do serviço quanto a conta vinculada ao Pasep, saques indevidos e desfalques, além da ausência de aplicação dos rendimentos estabelecidas pelo Conselho Diretor do referido programa; ii) a pretensão ao ressarcimento dos danos havidos em razão dos desfalques em conta individual vinculada ao Pasep se submete ao prazo prescricional decenal previsto pelo artigo 205 do Código Civil; e iii) o termo inicial para a contagem do prazo prescricional é o dia em que o titular, comprovadamente, toma ciência dos desfalques realizados na conta individual vinculada ao Pasep\", de modo que o Banco do Brasil S/A é parte legítima para figurar no polo passivo da ação de cobrança de Pasep, a competência é da justiça estadual, a prescrição da pretensão é decenal e seu termo a quo é a data do saque do saldo encontrado, quando o titular toma ciência dos desfalques. Mesmo que não fosse reconhecida a preclusão e a aplicação do CDC, ainda que por fundamento diverso, a inversão do ônus da prova se imporia com fundamento no 373, § 1º, do Código de Processo Civil. (TJ-MS - Agravo de Instrumento: 1405360-52.2022.8.12.0000 Campo Grande, Relator: Des. Amaury da Silva Kuklinski, Data de Julgamento: 14/12/2023, 3ª Câmara Cível, Data de Publicação: 15/12/2023) B - PRAZO PRESCRICIONAL DECENAL No Julgamento do tema 1150 do STJ, firmou-se o entendimento que o prazo prescricional para pretensão ao ressarcimento dos danos havidos em conta individual do PASEP, é o decenal previsto pelo art. 205 do Código Civil. C - TERMO INICIAL PARA CONTAGEM DO PRAZO Também, tomou-se entendimento no Julgamento do tema 1150 do STJ, que o termo de contagem inicial do prazo prescricional é o dia em que o titular, comprovadamente, toma ciência dos desfalques realizados na conta PASEP (art. 189 do Código Civil). V. EXIBIÇÃO DE DOCUMENTOS A instituição financeira requerida, dever-se-ia apresentar os extratos detalhados e evolução do saldo de todo o período da conta PASEP do Autor, de forma extrajudicial com simples pedido, contudo, os documentos apresentados foram apresentados em cópias de Microfilmagens em muitas vezes apagados e ou de dificil leitura, verdadeiros alfarabios, documentos de dificil leitura e interpretação. Onde da sua solicitação e entrega decorrem-se 5 meses, pois sua solicitação deu-se em 27/12/2023 e o recebimento em 25/04/2021. Tal informação só denota ao dificil acesso à informação ao Autor, onde o Banco Reu estabelece periodo com dilação temporal injustificavel, o torna-se necessário os pedidos Judiciais, ante a persistente ação do Banco Réu em fornecer os documentos de apuração desses valores de forma precária. A totalidade dos registros solicitados, necessarios, só foi entregue em documento posterior , extrato, em 10/07/2024, ou seja 8 meses após solicitação inicial. Conforme documento em anexo denominado de PASEP extrato. O Código de Processo Civil, prevê: Art. 396. O juiz pode ordenar que a parte exiba documento ou coisa que se encontre em seu poder. Art. 397. O pedido formulado pela parte conterá: I - a descrição, tão completa quanto possível, do documento ou da coisa, ou das categorias de documentos ou de coisas buscados; II - a finalidade da prova, com indicação dos fatos que se relacionam com o documento ou com a coisa, ou com suas categorias; III - as circunstâncias em que se funda o requerente para afirmar que o documento ou a coisa existe, ainda que a referência seja a categoria de documentos ou de coisas, e se acha em poder da parte contrária. Art. 398. O requerido dará sua resposta nos 5 (cinco) dias subsequentes à sua intimação. Parágrafo único. Se o requerido afirmar que não possui o documento ou a coisa, o juiz permitirá que o requerente prove, por qualquer meio, que a declaração não corresponde à verdade. Art. 399. O juiz não admitirá a recusa se: I - o requerido tiver obrigação legal de exibir; II - o requerido tiver aludido ao documento ou à coisa, no processo, com o intuito de constituir prova; III - o documento, por seu conteúdo, for comum às partes. Art. 400. Ao decidir o pedido, o juiz admitirá como verdadeiros os fatos que, por meio do documento ou da coisa, a parte pretendia provar se: I - o requerido não efetuar a exibição nem fizer nenhuma declaração no prazo do art. 398 ; II - a recusa for havida por ilegítima. Parágrafo único. Sendo necessário, o juiz pode adotar medidas indutivas, coercitivas, mandamentais ou sub-rogatórias para que o documento seja exibido. Portanto, frente a possibilidade prevista no CPC, deve a instituição Ré ser intimada a apresentar os extratos, sob pena de ser tido como referência em julgamento os cálculos apresentados na inicial. VI - DA INVERSÃO DO ÔNUS DA PROVA O direito do Autor de receber os valores do Pasep decorre da constituição Federal 1988, em seu artigo 7º, inciso XX, que garante aos trabalhadores urbanos e rurais o FGTS e outros benefícios previstos em lei. A Lei nº 8.036/90, que dispõe sobre o FGTS, não traz disposições específicas sobre a transferência dos valores do Pasep em caso de falecimento do titular. No entanto, a natureza alimentar do benefício e os princípios da dignidade da pessoa humana e da proteção à família, consagrados na Constituição Federal, autorizam a transmissão dos valores do Pasep aos dependentes do falecido. Como dispõe o artigo , inc. do , é direito básico do consumidor: “a facilitação da defesa de seus direitos, inclusive com a inversão do ônus da prova, a seu favor, no processo civil, quando, a critério do juiz, for verossímilhança a alegação ou quando for ele hipossuficiente, segundo as regras ordinárias de experiências.” Por oportuno, trazemos à baila o ensinamento de Plínio Lacerda Martins, in “Anotações ao . Conceito e noções básicas. DP & A Editora. RJ. 2001, p.27”: “Tendo em vista que o , no artigo ,VIII, prevê como direito básico do consumidor o direito à inversão do ônus da prova no processo quando a alegação for verossímil, facilitando assim a defesa dos direitos dos consumidores, e que esta inversão ao nosso juízo é ope judicis, não se justifica então a não-inversão do ônus da prova quando comprovada a verossimilhança ou mesmo a hipossufiência.” Saliente-se que no caso em foco, a Autor, sendo consumidor hipossuficiente e verificando-se a veracidade das alegações (prova documental que segue em anexo), detém então os requisitos para que o Douto Magistrado se digne conceder a Inversão do ônus da prova em favor do Autor. VII. DOS CÁLCULOS Diante dos dados apurados que puderam ser recuperados , do histórico financeiro economico, foi gerado um demosntrativo em planilha de cálculo, documento exibido e em anexo : Cita-se que o presente demonstrativo baseou-se em documentos de microfilmagens, extrato, fontes de dados oficiais do Banco Central do Brasil, Leis específicas que norteam a tese bem como baseado-se na jurisprudencia contemporanea e base de resoluções de tribunais brasileiros. A revisão do PASEP com a aplicação dos expurgos é importante por diversos motivos: Garantia de direitos: Assegura que os trabalhadores recebam o valor correto de seus recursos, corrigidos pela inflação. Justiça social: Corrige uma injustiça histórica, causada pelos planos econômicos que desvalorizaram a moeda. Fortalecimento da economia: Ao garantir que os trabalhadores tenham acesso aos recursos a que têm direito, contribui para o fortalecimento da economia. Os expurgos no PASEP é uma forma de corrigir as perdas inflacionárias causadas por planos econômicos passados, garantindo que os trabalhadores recebam o valor justo de seus recursos. A revisão do PASEP é um direito dos trabalhadores. VIII. DOS DANOS MORAIS Valor da Indenização por Prejuízos Causados por Má Administração Bancária: Uma Análise Complexa, o valor da indenização a ser pleiteada em um caso de prejuízos causados por má administração bancária, como créditos incorretos, é uma questão complexa e que varia de acordo com cada caso concreto. Com isso Fatores que influenciam o valor da indenização são eles Natureza do prejuízo: omitido retirado do patrimônio do autor valores que visivelmente poderia ter contribuído na vida do autor na realização de tarefas e sonhos que evidentemente não podem ser mensurados ou calculados, a dor causada pela falta é única, portanto cada um tem a sua e assim intangivelmente calculada. Danos materiais: Perda financeira direta, como valores indevidamente debitados ou não creditados na conta em muito sem a anuência do autor titular da conta. Essa conta ao longo da Gestão do réu Banco do Brasil, esteve as margens de atuação do autor, haja vistos que durante a mais de duas décadas que o réu geriu a conta, não há registros de repasses, relatórios para o autor, o banco réu agiu nesse período como proprietário e não administrador, sendo que contemporaneamente pode-se constatar a péssima administração executada. Danos morais: Sofrimento, angústia, constrangimento e outros danos psicológicos causados pela situação, não há em se falar na equidade do relacionamento, quando um cidadão em relação direta de cliente com uma instituição do porte do Banco Do Brasil, que tem como objetivo principal contribuir para o crescimento econômico, industrial, comercial e social do Brasil , vê sua conta e seus valores negados ou mesmo alterados por quem dever-se protege-los. Duração do problema: A gestão do atos falhos, realizados pelo Banco réu, pendura bem antes da ultima mudança de moeda, revela portanto ser o Banco réu participante de décadas da influência direta sobre os valores. Conduta do banco: O banco réu diante da reclamação do cliente mostra-se inerte, passivo , como não tivesse nenhuma responsabilidade sobre até aqui citado. A atitude demonstra má-fé ou negligência. A passividade, em um sentido jurídico, está intrinsecamente ligada à ideia de inércia, omissão ou falta de ação, Omissão: Aquele que, por ação ou omissão voluntária, negligência ou imprudência, violar direito e causar dano a outrem, ainda que exclusivamente moral, comete ato ilícito. (Art. 186 do Código Civil). Dever de agir: é um conceito que permeia diversas áreas do conhecimento, especialmente a filosofia, o direito e a ética. Ele se refere à obrigação moral ou legal que uma pessoa tem de realizar determinada ação, em detrimento de outras, em determinadas circunstâncias. Em determinadas situações, a lei impõe a obrigação de agir, sob pena de responsabilidade. A definição do valor da indenização é uma tarefa complexa que exige a análise de diversos fatores e a apresentação de provas que demonstrem o prejuízo sofrido pelo cliente. Diversos tribunais brasileiros já reconheceram o direito dos correntistas à indenização por danos morais e/ou perdas e danos em casos de débitos em atraso em contas do PASEP não resgatadas. Alguns exemplos: STJ: \"O Banco réu, por sua negligência e imperícia na gestão da conta PASEP do autor, causando-lhe transtornos e angústia, deve indenizá-lo por danos morais.\" (REsp 1.504.478/RS) TJSP: \"O banco falhou em seu dever de informação e gestão da conta PASEP do autor, causando-lhe prejuízos financeiros e sofrimento psicológico. Deve, portanto, indenizá-lo por danos morais e perdas e danos.\" (Apelação Cível 1.000.000-00/SP) É importante ressaltar que o valor da indenização será definido pelo juiz, após a análise das provas e dos argumentos apresentados pelas partes, segue este para formação de juízo o valor de R$ 15.000,00, como Danos Morais, haja vistos o descritivo de danos morais, nexos, a característica do ofensor infinitamente superior em relação ao autor, a reincidência do réu, a idade do autor defesa em lei e princípio da proporcionalidade e razoabilidade sem causar o enriquecimento injustificado do correntista, mas sim compatibilizando com os padrões sociais, considerando o valor do dano e a capacidade do banco réu. IX. DOS HONORÁRIOS ADVOCATÍCIOS Diante da complexidade da causa, do tempo despendido e Diligencias ao banco réu para obtenção de documentos, pelo advogado, do valor da condenação e da importância do resultado obtido, requer a condenação do réu ao pagamento, considerando-se o principio da razoabilidade, honorários advocatícios no valor de 20% (vinte por cento) sobre o valor da condenação, nos termos do artigo 85, § 2º, do Código de Processo Civil. X. DOS PEDIDOS Diante o exposto, requer à Vossa Excelência: A - A concessão do benefício da justiça gratuita, por ser a parte autora pessoa sem condições de arcar com as custas, honorários advocatícios e demais despesas processuais, ademais neste momento, sem prejuízo ao sustento próprio e de sua família consoante declaração anexa. B - A citação do Réu para, querendo, ofertar resposta em tempo hábil, sob pena de confissão e revelia; C - A Procedência da Ação, com a condenação do Réu a restituir os valores desfalcados da conta PASEP do autor, no montante de R$ 61.149,69 (Sessenta e um mil cento e quarenta e nove reais e sessenta e nove centavos), já deduzido o que foi recebido, atualizados até a presente data, conforme memória de cálculos (anexo); D - A inversão do ônus da prova e a apresentação dos documentos das microfilmagens adiante especificadas, uma vez que o banco Réu dignou a apresentar a parte Autora as informações que foram solicitadas, de forma segmentada e incompleta, sendo do fato, são documentos comuns às partes, sob pena do disposto no art. 400 do CPC. O Autor tem o direito de ter acesso às microfilmagens dos extratos de todo o período da conta do PASEP, nos termos do citado art. 396 CPC, haja vista que as instituições financeiras devem manter seus arquivos devidamente organizados e catalogados de modo a permitir uma fácil e célere consulta, a teor do disposto no § 1º do art. 1º da Resolução nº 913/84 do BACEN. E - A condenação do Réu ao pagamento das custas e demais despesas processuais, inclusive em honorários advocatícios sucumbenciais, que deverão ser arbitrados por este Juízo, conforme norma do artigo 85 do CPC expressos como sugestão de 20%; F - Requer a produção de todos os meios de prova em direito admitidos, notadamente a prova documental, testemunhal e depoimento pessoal do representante do Réu, sob pena de confissão ficta. G - Em homenagem ao princípio da razoável duração do processo, o Promovente opta pela não realização de audiência conciliatória (CPC, art. 319, inc. VII), haja vista a escassa possibilidade de transação judicial entre os litigantes. Dá-se à causa o valor de R$ 0,00 (valor extenso). Nestes termos, pede e espera deferimento.', 'texto.png', NULL);

